// packages/core/src/components/Accordion/Accordion.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";
import { AccordionContext, type AccordionVariant, AccordionItem } from "./AccordionItem";

export const accordionVariants = cva("w-full transition-all duration-200", {
  variants: {
    variant: {
      light: "border-t border-border",
      bordered: "border border-border rounded-xl overflow-hidden bg-card text-card-foreground",
      shadow: "space-y-2",
      splitted: "space-y-3",
    },
  },
  defaultVariants: {
    variant: "light",
  },
});

export interface AccordionProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof accordionVariants> {
  selectionMode?: "single" | "multiple";
  selectedKeys?: string[] | Set<string>;
  defaultSelectedKeys?: string[] | Set<string>;
  onSelectionChange?: (keys: string[]) => void;
  isCompact?: boolean;
  isDisabled?: boolean;
  showDivider?: boolean;
  classNames?: {
    base?: string;
  };
}

export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      className,
      classNames,
      variant = "light",
      selectionMode = "single",
      selectedKeys: propSelectedKeys,
      defaultSelectedKeys = [],
      onSelectionChange,
      isCompact = false,
      isDisabled = false,
      showDivider = true,
      children,
      ...props
    },
    ref
  ) => {
    // Normalise defaultSelectedKeys to Set
    const initialKeys = React.useMemo(() => {
      if (defaultSelectedKeys instanceof Set) return defaultSelectedKeys;
      return new Set(defaultSelectedKeys);
    }, [defaultSelectedKeys]);

    const [uncontrolledKeys, setUncontrolledKeys] = React.useState<Set<string>>(initialKeys);

    const isControlled = propSelectedKeys !== undefined;
    const currentKeys = React.useMemo(() => {
      if (!isControlled) return uncontrolledKeys;
      if (propSelectedKeys instanceof Set) return propSelectedKeys;
      return new Set(propSelectedKeys);
    }, [isControlled, propSelectedKeys, uncontrolledKeys]);

    const toggleKey = React.useCallback(
      (key: string) => {
        const next = new Set(currentKeys);
        if (selectionMode === "single") {
          if (next.has(key)) {
            next.clear();
          } else {
            next.clear();
            next.add(key);
          }
        } else {
          // multiple
          if (next.has(key)) {
            next.delete(key);
          } else {
            next.add(key);
          }
        }

        if (!isControlled) {
          setUncontrolledKeys(next);
        }
        onSelectionChange?.(Array.from(next));
      },
      [currentKeys, selectionMode, isControlled, onSelectionChange]
    );

    const contextValue = React.useMemo(
      () => ({
        selectedKeys: currentKeys,
        toggleKey,
        variant: variant || "light",
        isCompact,
        isDisabled,
        showDivider,
      }),
      [currentKeys, toggleKey, variant, isCompact, isDisabled, showDivider]
    );

    return (
      <AccordionContext.Provider value={contextValue}>
        <div
          ref={ref}
          className={cn(accordionVariants({ variant }), classNames?.base, className)}
          {...props}
        >
          {children}
        </div>
      </AccordionContext.Provider>
    );
  }
);
Accordion.displayName = "Accordion";

// packages/core/src/components/Accordion/AccordionItem.tsx
"use client";
import * as React from "react";
import { ChevronDown } from "lucide-react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type AccordionVariant = "light" | "shadow" | "bordered" | "splitted";

export interface AccordionContextValue {
  selectedKeys: Set<string>;
  toggleKey: (key: string) => void;
  variant: AccordionVariant;
  isCompact: boolean;
  isDisabled: boolean;
  showDivider: boolean;
}

export const AccordionContext = React.createContext<AccordionContextValue | null>(null);

export function useAccordionContext() {
  return React.useContext(AccordionContext);
}

export const accordionItemVariants = cva("transition-colors duration-150", {
  variants: {
    variant: {
      light: "border-b border-border last:border-b-0",
      bordered: "border-b border-border last:border-b-0",
      shadow:
        "bg-card text-card-foreground shadow-sm border border-border/80 rounded-xl mb-2 last:mb-0",
      splitted:
        "bg-card text-card-foreground border border-border rounded-xl mb-3 shadow-xs last:mb-0",
    },
  },
  defaultVariants: {
    variant: "light",
  },
});

export interface AccordionItemProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  itemKey?: string;
  value?: string;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  startContent?: React.ReactNode;
  indicator?: React.ReactNode | ((props: { isOpen: boolean }) => React.ReactNode);
  hideIndicator?: boolean;
  isDisabled?: boolean;
  classNames?: {
    base?: string;
    trigger?: string;
    titleWrapper?: string;
    title?: string;
    subtitle?: string;
    indicator?: string;
    content?: string;
  };
}

export const AccordionItem = React.forwardRef<HTMLDivElement, AccordionItemProps>(
  (
    {
      className,
      classNames,
      itemKey,
      value,
      title,
      subtitle,
      startContent,
      indicator,
      hideIndicator = false,
      isDisabled: propDisabled = false,
      children,
      id: customId,
      ...props
    },
    ref
  ) => {
    const context = useAccordionContext();
    const generatedId = React.useId();

    const actualKey = itemKey || value || customId || generatedId;

    const isOpen = context ? context.selectedKeys.has(actualKey) : false;
    const isDisabled = propDisabled || (context?.isDisabled ?? false);
    const variant = context?.variant || "light";
    const isCompact = context?.isCompact || false;

    const triggerId = `${generatedId}-trigger`;
    const contentId = `${generatedId}-content`;

    const handleToggle = () => {
      if (!isDisabled && context) {
        context.toggleKey(actualKey);
      }
    };

    return (
      <div
        ref={ref}
        className={cn(
          accordionItemVariants({ variant }),
          isDisabled ? "pointer-events-none opacity-50" : "",
          classNames?.base,
          className
        )}
        {...props}
      >
        <h3 className="m-0 p-0 font-normal">
          <button
            type="button"
            id={triggerId}
            aria-expanded={isOpen}
            aria-controls={contentId}
            aria-disabled={isDisabled ? true : undefined}
            disabled={isDisabled}
            onClick={handleToggle}
            className={cn(
              "focus-visible:ring-ring focus-visible:ring-offset-background flex w-full cursor-pointer items-center justify-between gap-3 rounded-lg text-left transition-all duration-150 select-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none",
              isCompact ? "px-3 py-2.5" : "px-4 py-4",
              classNames?.trigger
            )}
          >
            {startContent && (
              <span className="text-muted-foreground flex shrink-0 items-center justify-center">
                {startContent}
              </span>
            )}

            <div className={cn("flex min-w-0 flex-1 flex-col text-left", classNames?.titleWrapper)}>
              <span
                className={cn(
                  "text-foreground truncate font-medium",
                  isCompact ? "text-sm" : "text-base",
                  classNames?.title
                )}
              >
                {title}
              </span>
              {subtitle && (
                <span className={cn("text-muted-foreground mt-0.5 text-xs", classNames?.subtitle)}>
                  {subtitle}
                </span>
              )}
            </div>

            {!hideIndicator && (
              <span
                aria-hidden="true"
                className={cn(
                  "text-muted-foreground shrink-0 transition-transform duration-200 ease-out",
                  isOpen ? "text-foreground rotate-180" : "",
                  classNames?.indicator
                )}
              >
                {typeof indicator === "function" ? (
                  indicator({ isOpen })
                ) : indicator ? (
                  indicator
                ) : (
                  <ChevronDown className="h-4 w-4" />
                )}
              </span>
            )}
          </button>
        </h3>

        {/* Collapsible Content */}
        <div
          id={contentId}
          role="region"
          aria-labelledby={triggerId}
          className={cn(
            "text-muted-foreground grid overflow-hidden transition-all duration-200 ease-in-out",
            isOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
          )}
        >
          <div className="overflow-hidden">
            <div
              className={cn(
                "pb-4 text-sm leading-relaxed",
                isCompact ? "px-3 pt-1 pb-3" : "px-4 pt-1 pb-4",
                classNames?.content
              )}
            >
              {children}
            </div>
          </div>
        </div>
      </div>
    );
  }
);
AccordionItem.displayName = "AccordionItem";

// packages/core/src/components/Accordion/index.ts
export * from "./AccordionItem";
export * from "./Accordion";

// packages/core/src/components/Alert/Alert.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { X } from "lucide-react";
import { cn } from "../utils/cn";

export type AlertVariant = "solid" | "flat" | "soft" | "bordered" | "outline";
export type AlertColor = "primary" | "secondary" | "success" | "danger" | "warning" | "info";

const alertVariants = cva(
  "relative flex w-full items-start gap-3.5 p-4 rounded-2xl text-sm transition-all duration-200",
  {
    variants: {
      variant: {
        solid: "shadow-xs text-white",
        flat: "shadow-none",
        soft: "shadow-none",
        bordered: "border-2 bg-transparent",
        outline: "border-2 bg-transparent",
      },
      color: {
        primary: "",
        secondary: "",
        success: "",
        danger: "",
        warning: "",
        info: "",
      },
    },
    compoundVariants: [
      // Solid Variants
      {
        variant: "solid",
        color: "primary",
        className: "bg-primary text-primary-foreground shadow-primary/20",
      },
      {
        variant: "solid",
        color: "secondary",
        className: "bg-secondary text-secondary-foreground shadow-secondary/20",
      },
      {
        variant: "solid",
        color: "success",
        className: "bg-emerald-600 text-white shadow-emerald-600/20 dark:bg-emerald-500",
      },
      {
        variant: "solid",
        color: "danger",
        className: "bg-rose-600 text-white shadow-rose-600/20 dark:bg-rose-500",
      },
      {
        variant: "solid",
        color: "warning",
        className: "bg-amber-500 text-zinc-950 font-bold shadow-amber-500/20 dark:bg-amber-400",
      },
      {
        variant: "solid",
        color: "info",
        className: "bg-sky-600 text-white shadow-sky-600/20 dark:bg-sky-500",
      },

      // Flat Variants
      {
        variant: ["flat", "soft"],
        color: "primary",
        className:
          "bg-primary-50 text-primary-700 border border-primary-200 dark:bg-primary-500/15 dark:text-primary-400 dark:border-primary-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "secondary",
        className:
          "bg-secondary-50 text-secondary-700 border border-secondary-200 dark:bg-secondary-500/15 dark:text-secondary-400 dark:border-secondary-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "success",
        className:
          "bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-500/15 dark:text-emerald-400 dark:border-emerald-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "danger",
        className:
          "bg-rose-50 text-rose-700 border border-rose-200 dark:bg-rose-500/15 dark:text-rose-400 dark:border-rose-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "warning",
        className:
          "bg-amber-50 text-amber-700 border border-amber-200 dark:bg-amber-500/15 dark:text-amber-400 dark:border-amber-500/20",
      },
      {
        variant: ["flat", "soft"],
        color: "info",
        className:
          "bg-sky-50 text-sky-700 border border-sky-200 dark:bg-sky-500/15 dark:text-sky-400 dark:border-sky-500/20",
      },

      // Bordered Variants
      {
        variant: ["bordered", "outline"],
        color: "primary",
        className:
          "border-primary-600 text-primary-700 dark:border-primary-500 dark:text-primary-400",
      },
      {
        variant: ["bordered", "outline"],
        color: "secondary",
        className:
          "border-secondary-600 text-secondary-700 dark:border-secondary-500 dark:text-secondary-400",
      },
      {
        variant: ["bordered", "outline"],
        color: "success",
        className:
          "border-emerald-600 text-emerald-700 dark:border-emerald-500 dark:text-emerald-400",
      },
      {
        variant: ["bordered", "outline"],
        color: "danger",
        className: "border-rose-600 text-rose-700 dark:border-rose-500 dark:text-rose-400",
      },
      {
        variant: ["bordered", "outline"],
        color: "warning",
        className: "border-amber-500 text-amber-700 dark:border-amber-400 dark:text-amber-400",
      },
      {
        variant: ["bordered", "outline"],
        color: "info",
        className: "border-sky-600 text-sky-700 dark:border-sky-500 dark:text-sky-400",
      },
    ],
    defaultVariants: {
      variant: "flat",
      color: "primary",
    },
  }
);

export interface AlertProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "title" | "color">,
    VariantProps<typeof alertVariants> {
  title?: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
  isClosable?: boolean;
  onClose?: () => void;
}

const Alert = React.forwardRef<HTMLDivElement, AlertProps>(
  (
    {
      className,
      variant = "flat",
      color = "primary",
      title,
      description,
      icon,
      isClosable = false,
      onClose,
      children,
      ...props
    },
    ref
  ) => {
    const [isOpen, setIsOpen] = React.useState(true);

    const handleClose = () => {
      setIsOpen(false);
      onClose?.();
    };

    if (!isOpen) return null;

    // Determine close button styling according to variant
    const getCloseButtonClass = () => {
      if (variant === "solid") {
        if (color === "warning") {
          return "text-zinc-950/70 hover:text-zinc-950 hover:bg-black/10 dark:hover:bg-black/20";
        }
        return "text-white/80 hover:text-white hover:bg-white/20 dark:hover:bg-white/15";
      }
      return "text-zinc-500 hover:text-zinc-900 hover:bg-zinc-200/50 dark:text-zinc-400 dark:hover:text-zinc-100 dark:hover:bg-zinc-800/50";
    };

    return (
      <div
        ref={ref}
        role="alert"
        className={cn(alertVariants({ variant, color, className }))}
        {...props}
      >
        {/* Left Icon Slot */}
        {icon && (
          <div className="shrink-0 pt-0.5" aria-hidden="true">
            {icon}
          </div>
        )}

        {/* Center Content Area */}
        <div className="min-w-0 flex-1 space-y-1">
          {title && <h5 className="leading-tight font-semibold tracking-tight">{title}</h5>}
          {description && (
            <div className="text-xs leading-relaxed font-normal opacity-90 sm:text-sm">
              {description}
            </div>
          )}
          {children && (
            <div className="text-xs leading-relaxed font-normal opacity-90 sm:text-sm">
              {children}
            </div>
          )}
        </div>

        {/* Right Close Button */}
        {isClosable && (
          <button
            type="button"
            onClick={handleClose}
            aria-label="Close alert"
            className={cn(
              "-mt-1.5 -mr-1.5 shrink-0 rounded-xl p-1 transition-all focus-visible:ring-2 focus-visible:ring-zinc-950 focus-visible:outline-none active:scale-95 dark:focus-visible:ring-zinc-300",
              getCloseButtonClass()
            )}
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>
    );
  }
);

Alert.displayName = "Alert";

export { Alert, alertVariants };

"use client";
import * as React from "react";
import {
  Area,
  AreaChart as RechartsAreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  Legend,
} from "recharts";
import { cn } from "../utils/cn";
import { ChartTooltip } from "../ChartTooltip";
import { motion } from "framer-motion";
import { useId } from "react";

export interface AreaChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  data: any[];
  index: string;
  categories: string[];
  colors?: string[];
  valueFormatter?: (value: number) => string;
  showXAxis?: boolean;
  showYAxis?: boolean;
  showGridLines?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  curveType?: "linear" | "natural" | "monotone" | "step";
  connectNulls?: boolean;
  strokeWidth?: number;
  strokeDasharray?: string | string[];
  type?: "default" | "stacked" | "percent";
  variant?: "default" | "sparkline";
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  children?: React.ReactNode;
}

const defaultColors = [
  "var(--color-primary-500, #3b82f6)",
  "var(--color-secondary-500, #a855f7)",
  "var(--color-success-500, #22c55e)",
  "var(--color-warning-500, #eab308)",
  "var(--color-danger-500, #ef4444)",
  "var(--color-info-500, #0ea5e9)",
];

const AreaChart = React.forwardRef<HTMLDivElement, AreaChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showXAxis = true,
      showYAxis = true,
      showGridLines = true,
      showLegend = true,
      showTooltip = true,
      curveType = "monotone",
      connectNulls = false,
      strokeWidth = 2,
      strokeDasharray,
      type = "default",
      variant = "default",
      customTooltip,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const isSparkline = variant === "sparkline";

    // Use responsive heights based on the variant
    const heightClass = isSparkline ? "h-[120px]" : "h-[350px]";
    const chartId = useId();

    return (
      <motion.div
        ref={ref}
        className={cn("w-full", heightClass, className)}
        {...props}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsAreaChart
            data={data}
            margin={{
              top: 24,
              right: 24,
              left: 24,
              bottom: showLegend && !isSparkline ? 80 : 40,
            }}
            stackOffset={type === "stacked" ? "none" : type === "percent" ? "expand" : undefined}
          >
            {showGridLines && !isSparkline && (
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                stroke="currentColor"
                className="text-zinc-200 dark:text-zinc-800"
              />
            )}

            {showXAxis && !isSparkline && (
              <XAxis
                dataKey={index}
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickMargin={16}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showYAxis && !isSparkline && (
              <YAxis
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickFormatter={valueFormatter}
                tickMargin={16}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showTooltip && (
              <Tooltip
                content={
                  customTooltip ? customTooltip : <ChartTooltip valueFormatter={valueFormatter} />
                }
              />
            )}

            {showLegend && !isSparkline && (
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                wrapperStyle={{ fontSize: "14px", paddingTop: "20px" }}
              />
            )}

            <defs>
              {categories.map((category, i) => (
                <linearGradient
                  key={`${chartId}-colorUv-${i}`}
                  id={`${chartId}-colorUv-${i}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop offset="5%" stopColor={colors[i % colors.length]} stopOpacity={0.3} />
                  <stop offset="95%" stopColor={colors[i % colors.length]} stopOpacity={0} />
                </linearGradient>
              ))}
            </defs>

            {categories.map((category, i) => (
              <Area
                key={category}
                type={curveType}
                dataKey={category}
                stroke={colors[i % colors.length]}
                strokeWidth={strokeWidth}
                strokeDasharray={
                  Array.isArray(strokeDasharray)
                    ? strokeDasharray[i % strokeDasharray.length]
                    : strokeDasharray
                }
                fillOpacity={1}
                fill={`url(#${chartId}-colorUv-${i})`}
                connectNulls={connectNulls}
                stackId={type === "stacked" || type === "percent" ? "1" : undefined}
                dot={false}
                activeDot={(props: any) => {
                  const { cx, cy, stroke, fill, dataKey } = props;
                  if (cx === undefined || cy === undefined || isNaN(cx) || isNaN(cy)) return null;
                  return (
                    <circle cx={cx} cy={cy} r={5} fill={colors[i % colors.length]} stroke="none" />
                  );
                }}
              />
            ))}
            {children}
          </RechartsAreaChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

AreaChart.displayName = "AreaChart";

export { AreaChart };

// packages/core/src/components/Avatar/Avatar.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type AvatarSize = "sm" | "md" | "lg" | "xl";
export type AvatarRadius = "none" | "md" | "lg" | "full";
export type AvatarColor = "default" | "primary" | "success" | "danger";

const avatarVariants = cva(
  "relative inline-flex shrink-0 items-center justify-center overflow-hidden select-none font-semibold tracking-tight transition-all duration-200 ring-1 ring-zinc-950/5 dark:ring-white/10",
  {
    variants: {
      size: {
        sm: "h-8 w-8 text-xs",
        md: "h-10 w-10 text-sm",
        lg: "h-12 w-12 text-base",
        xl: "h-14 w-14 text-lg",
      },
      radius: {
        none: "rounded-none",
        md: "rounded-xl",
        lg: "rounded-2xl",
        full: "rounded-full",
      },
      color: {
        default: "bg-zinc-200 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-400",
        primary: "bg-primary text-primary-foreground",
        success: "bg-emerald-600 text-white dark:bg-emerald-500",
        danger: "bg-rose-600 text-white dark:bg-rose-500",
      },
    },
    defaultVariants: {
      size: "md",
      radius: "full",
      color: "default",
    },
  }
);

export interface AvatarProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "color">, VariantProps<typeof avatarVariants> {
  src?: string;
  alt?: string;
  name?: string;
  onError?: () => void;
}

// Utility to generate initials from a name string (e.g. "John Doe" -> "JD", "Sarah" -> "S")
function getInitials(name?: string): string {
  if (!name) return "";
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) {
    return parts[0].substring(0, 2).toUpperCase();
  }
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>(
  (
    {
      className,
      src,
      alt = "Avatar",
      name,
      size = "md",
      radius = "full",
      color = "default",
      onError,
      children,
      ...props
    },
    ref
  ) => {
    const [imageError, setImageError] = React.useState(false);

    // Reset error state when src changes
    React.useEffect(() => {
      setImageError(false);
    }, [src]);

    const handleImageError = () => {
      setImageError(true);
      onError?.();
    };

    const hasValidImage = Boolean(src) && !imageError;
    const initials = getInitials(name);

    return (
      <div
        ref={ref}
        className={cn(avatarVariants({ size, radius, color, className }))}
        aria-label={name || alt}
        role="img"
        {...props}
      >
        {hasValidImage ? (
          <img
            src={src}
            alt={alt || name || "Avatar"}
            onError={handleImageError}
            referrerPolicy="no-referrer"
            className="h-full w-full object-cover"
          />
        ) : initials ? (
          <span className="leading-none font-semibold uppercase">{initials}</span>
        ) : children ? (
          children
        ) : (
          <svg
            className="h-3/5 w-3/5 fill-current opacity-60"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
          </svg>
        )}
      </div>
    );
  }
);

Avatar.displayName = "Avatar";

export { Avatar, avatarVariants };

