const placementStyles: Record<BadgePlacement, string> = {
  "top-right": "top-0 right-0 translate-x-1/2 -translate-y-1/2",
  "top-left": "top-0 left-0 -translate-x-1/2 -translate-y-1/2",
  "bottom-right": "bottom-0 right-0 translate-x-1/2 translate-y-1/2",
  "bottom-left": "bottom-0 left-0 -translate-x-1/2 translate-y-1/2",
};

export interface BadgeProps
  extends
    Omit<React.HTMLAttributes<HTMLSpanElement>, "color" | "content">,
    VariantProps<typeof badgeVariants> {
  /**
   * Content to render inside the floating badge (when wrapping child elements).
   * If omitted, renders as a standalone badge using `children`.
   */
  content?: React.ReactNode;
  /**
   * Corner placement when used as a floating notification on a wrapped element.
   * @default "top-right"
   */
  placement?: BadgePlacement;
  /**
   * Shows a small indicator dot without text content when true.
   * @default false
   */
  isDot?: boolean;
  /**
   * Controls whether the badge is visible.
   * @default true
   */
  isInvisible?: boolean;
}

const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  (
    {
      className,
      variant = "solid",
      color = "primary",
      size = "md",
      content,
      placement = "top-right",
      isDot = false,
      isInvisible = false,
      children,
      ...props
    },
    ref
  ) => {
    // Mode 1: Floating Badge wrapping child elements (Avatar, Button, Icon, etc.)
    const isFloating = children !== undefined && (content !== undefined || isDot);

    const badgeContent = (
      <span
        ref={ref}
        className={cn(
          badgeVariants({ variant, color, size }),
          isFloating && [
            "ring-background absolute z-10 box-border ring-2",
            placementStyles[placement],
            isDot && "h-2.5 w-2.5 min-w-0 rounded-full p-0 px-0 py-0",
          ],
          isInvisible && "hidden",
          className
        )}
        {...props}
      >
        {!isDot && (content ?? children)}
      </span>
    );

    if (isFloating) {
      return (
        <span className="relative inline-flex shrink-0">
          {children}
          {badgeContent}
        </span>
      );
    }

    // Mode 2: Standalone inline badge (e.g. tag label in table or card)
    return (
      <span
        ref={ref}
        className={cn(
          badgeVariants({ variant, color, size }),
          isDot && "h-2.5 w-2.5 min-w-0 rounded-full p-0 px-0 py-0",
          isInvisible && "hidden",
          className
        )}
        {...props}
      >
        {!isDot && children}
      </span>
    );
  }
);

Badge.displayName = "Badge";

export { Badge, badgeVariants };

"use client";
import * as React from "react";
import {
  Bar,
  BarChart as RechartsBarChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  Legend,
} from "recharts";
import { cn } from "../utils/cn";
import { ChartTooltip } from "../ChartTooltip";
import { motion } from "framer-motion";

export interface BarChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  data: any[];
  index: string;
  categories: string[];
  colors?: string[];
  valueFormatter?: (value: number) => string;
  showXAxis?: boolean;
  showYAxis?: boolean;
  showGridLines?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  type?: "default" | "stacked" | "percent";
  variant?: "default" | "sparkline";
  layout?: "horizontal" | "vertical";
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  barRadius?: number | [number, number, number, number];
  children?: React.ReactNode;
}

const defaultColors = [
  "var(--color-primary-500, #3b82f6)",
  "var(--color-secondary-500, #a855f7)",
  "var(--color-success-500, #22c55e)",
  "var(--color-warning-500, #eab308)",
  "var(--color-danger-500, #ef4444)",
  "var(--color-info-500, #0ea5e9)",
];

const BarChart = React.forwardRef<HTMLDivElement, BarChartProps>(
  (
    {
      data,
      index,
      categories,
      colors = defaultColors,
      valueFormatter = (value: number) => value.toString(),
      showXAxis = true,
      showYAxis = true,
      showGridLines = true,
      showLegend = true,
      showTooltip = true,
      type = "default",
      variant = "default",
      layout = "horizontal",
      customTooltip,
      barRadius = 4,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const isSparkline = variant === "sparkline";
    const heightClass = isSparkline ? "h-[120px]" : "h-[350px]";
    const isVertical = layout === "vertical";

    return (
      <motion.div
        ref={ref}
        className={cn("w-full", heightClass, className)}
        {...props}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsBarChart
            data={data}
            layout={layout}
            margin={{
              top: 24,
              right: 24,
              left: 24,
              bottom: showLegend && !isSparkline ? 80 : 40,
            }}
          >
            {showGridLines && !isSparkline && (
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={isVertical}
                horizontal={!isVertical}
                stroke="currentColor"
                className="text-zinc-200 dark:text-zinc-800"
              />
            )}

            {showXAxis && !isSparkline && (
              <XAxis
                {...(!isVertical ? { dataKey: index, type: "category" } : { type: "number" })}
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickMargin={16}
                tickFormatter={isVertical ? valueFormatter : undefined}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showYAxis && !isSparkline && (
              <YAxis
                {...(isVertical ? { dataKey: index, type: "category", width: 60 } : {})}
                tickLine={false}
                axisLine={false}
                tick={{ fontSize: 12 }}
                tickMargin={16}
                tickFormatter={isVertical ? undefined : valueFormatter}
                className="text-zinc-500 dark:text-zinc-400"
              />
            )}

            {showTooltip && (
              <Tooltip
                cursor={{ fill: "currentColor", opacity: 0.05 }}
                content={
                  customTooltip ? customTooltip : <ChartTooltip valueFormatter={valueFormatter} />
                }
              />
            )}

            {showLegend && !isSparkline && (
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                wrapperStyle={{ fontSize: "14px", paddingTop: "20px" }}
              />
            )}

            {categories.map((category, i) => (
              <Bar
                key={category}
                dataKey={category}
                fill={colors[i % colors.length]}
                radius={
                  type === "stacked"
                    ? undefined
                    : typeof barRadius === "number"
                      ? isVertical
                        ? [0, barRadius, barRadius, 0]
                        : [barRadius, barRadius, 0, 0]
                      : barRadius
                }
                stackId={type === "stacked" || type === "percent" ? "1" : undefined}
              />
            ))}
            {children}
          </RechartsBarChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

BarChart.displayName = "BarChart";

export { BarChart };

// packages/core/src/components/Breadcrumbs/Breadcrumbs.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import { cn } from "../utils/cn";

export type BreadcrumbsSize = "sm" | "md" | "lg";
export type BreadcrumbsVariant = "solid" | "bordered" | "light";
export type BreadcrumbsUnderline = "none" | "hover" | "always" | "active";

/* -------------------------------------------------------------------------------------------------
 * Context
 * -----------------------------------------------------------------------------------------------*/

interface BreadcrumbsContextValue {
  size: BreadcrumbsSize;
  separator: React.ReactNode;
  underline: BreadcrumbsUnderline;
  isDisabled: boolean;
}

const BreadcrumbsContext = React.createContext<BreadcrumbsContextValue>({
  size: "md",
  separator: <ChevronRight className="h-3.5 w-3.5 text-zinc-400 dark:text-zinc-500" />,
  underline: "hover",
  isDisabled: false,
});

export const useBreadcrumbsContext = () => React.useContext(BreadcrumbsContext);

/* -------------------------------------------------------------------------------------------------
 * Breadcrumbs (Root)
 * -----------------------------------------------------------------------------------------------*/

export const breadcrumbsVariants = cva("flex flex-wrap items-center", {
  variants: {
    variant: {
      light: "bg-transparent p-0",
      bordered:
        "border border-zinc-200 dark:border-zinc-800 bg-white/60 dark:bg-zinc-900/60 rounded-xl px-3 py-2 shadow-2xs backdrop-blur-sm",
      solid:
        "bg-zinc-100 dark:bg-zinc-800/80 rounded-xl px-3.5 py-2 text-zinc-800 dark:text-zinc-200",
    },
    size: {
      sm: "text-xs gap-1.5",
      md: "text-sm gap-2",
      lg: "text-base gap-2.5",
    },
  },
  defaultVariants: {
    variant: "light",
    size: "md",
  },
});

export interface BreadcrumbsProps
  extends React.HTMLAttributes<HTMLElement>, VariantProps<typeof breadcrumbsVariants> {
  separator?: React.ReactNode;
  underline?: BreadcrumbsUnderline;
  isDisabled?: boolean;
  maxItems?: number;
  itemsBeforeCollapse?: number;
  itemsAfterCollapse?: number;
  renderEllipsis?: () => React.ReactNode;
  children: React.ReactNode;
}

export const Breadcrumbs = React.forwardRef<HTMLElement, BreadcrumbsProps>(
  (
    {
      separator = <ChevronRight className="h-3.5 w-3.5 text-zinc-400 dark:text-zinc-500" />,
      variant = "light",
      size = "md",
      underline = "hover",
      isDisabled = false,
      maxItems,
      itemsBeforeCollapse = 1,
      itemsAfterCollapse = 1,
      renderEllipsis,
      children,
      className,
      ...props
    },
    ref
  ) => {
    const rawItems = React.Children.toArray(children).filter(Boolean);

    let displayItems = rawItems;
    if (maxItems && rawItems.length > maxItems) {
      const before = rawItems.slice(0, itemsBeforeCollapse);
      const after = rawItems.slice(rawItems.length - itemsAfterCollapse);
      const ellipsisNode = (
        <li
          key="breadcrumbs-ellipsis"
          className="flex items-center text-zinc-400 dark:text-zinc-500"
        >
          {renderEllipsis ? (
            renderEllipsis()
          ) : (
            <span className="flex h-6 w-6 items-center justify-center rounded-md hover:bg-zinc-100 dark:hover:bg-zinc-800">
              <MoreHorizontal className="h-4 w-4" />
            </span>
          )}
          <span className="mx-1.5 flex items-center select-none" aria-hidden="true">
            {separator}
          </span>
        </li>
      );

      displayItems = [...before, ellipsisNode, ...after];
    }

    return (
      <BreadcrumbsContext.Provider
        value={{
          size: size || "md",
          separator,
          underline,
          isDisabled,
        }}
      >
        <nav ref={ref} aria-label="Breadcrumb" className={cn("w-fit", className)} {...props}>
          <ol className={cn(breadcrumbsVariants({ variant, size }))}>
            {displayItems.map((child, index) => {
              const isLast = index === displayItems.length - 1;
              return (
                <React.Fragment key={index}>
                  {child}
                  {!isLast && (
                    <li
                      aria-hidden="true"
                      className="flex items-center text-zinc-400 select-none dark:text-zinc-600"
                    >
                      {separator}
                    </li>
                  )}
                </React.Fragment>
              );
            })}
          </ol>
        </nav>
      </BreadcrumbsContext.Provider>
    );
  }
);
Breadcrumbs.displayName = "Breadcrumbs";

/* -------------------------------------------------------------------------------------------------
 * BreadcrumbItem
 * -----------------------------------------------------------------------------------------------*/

export interface BreadcrumbItemProps extends React.LiHTMLAttributes<HTMLLIElement> {
  href?: string;
  isCurrent?: boolean;
  isDisabled?: boolean;
  startContent?: React.ReactNode;
  endContent?: React.ReactNode;
  onPress?: () => void;
  children: React.ReactNode;
}

export const BreadcrumbItem = React.forwardRef<HTMLLIElement, BreadcrumbItemProps>(
  (
    {
      href,
      isCurrent = false,
      isDisabled: propDisabled = false,
      startContent,
      endContent,
      onPress,
      children,
      className,
      onClick,
      ...props
    },
    ref
  ) => {
    const context = useBreadcrumbsContext();
    const disabled = propDisabled || context.isDisabled;

    const underlineClasses = {
      none: "no-underline",
      hover: "hover:underline",
      always: "underline",
      active: isCurrent ? "underline" : "no-underline",
    }[context.underline];

    const content = (
      <span className="flex items-center gap-1.5">
        {startContent && <span className="shrink-0">{startContent}</span>}
        <span>{children}</span>
        {endContent && <span className="shrink-0">{endContent}</span>}
      </span>
    );

    const handleClick = (e: React.MouseEvent<any>) => {
      if (disabled) {
        e.preventDefault();
        return;
      }
      onPress?.();
      onClick?.(e);
    };

    return (
      <li
        ref={ref}
        aria-current={isCurrent ? "page" : undefined}
        className={cn(
          "inline-flex items-center transition-colors duration-150",
          isCurrent
            ? "cursor-default font-semibold text-zinc-900 dark:text-zinc-50"
            : disabled
              ? "pointer-events-none cursor-not-allowed text-zinc-400 dark:text-zinc-600"
              : "cursor-pointer text-zinc-600 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100",
          className
        )}
        {...props}
      >
        {href && !isCurrent ? (
          <a
            href={href}
            onClick={handleClick}
            className={cn(
              "inline-flex items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-indigo-500",
              underlineClasses
            )}
          >
            {content}
          </a>
        ) : (
          <span
            aria-current={isCurrent ? "page" : undefined}
            onClick={handleClick}
            className={cn(
              "inline-flex items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-indigo-500",
              underlineClasses
            )}
          >
            {content}
          </span>
        )}
      </li>
    );
  }
);
BreadcrumbItem.displayName = "BreadcrumbItem";

