  /**
   * Function to determine if a specific date is disabled
   */
  isDateDisabled?: (date: Date) => boolean;
  /**
   * Disable past dates
   */
  disablePastDates?: boolean;
  /**
   * Disable future dates
   */
  disableFutureDates?: boolean;
  /**
   * Disable Saturday and Sunday
   */
