  /**
   * Whether the input is in an invalid state
   */
  isInvalid?: boolean;
  /**
   * Include fast presets shortcuts
   */
  presets?: CalendarPreset[];
  /**
   * Enable default quick presets
   */
  showPresets?: boolean;
  /**
   * Show time picker inside calendar
   */
  showTime?: boolean;
  /**
   * Time format (12h or 24h)
   */
  timeFormat?: "12h" | "24h";
