// packages/core/src/components/ComboBox/ComboBox.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export interface ComboBoxOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export type ComboBoxVariant = "bordered" | "flat";
export type ComboBoxSize = "sm" | "md" | "lg";

const comboBoxInputVariants = cva(
  "w-full rounded-xl transition-all duration-150 font-normal outline-none text-foreground placeholder:text-muted-foreground disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        bordered:
          "bg-background border border-border hover:border-foreground/30 focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/20 shadow-2xs",
        flat: "bg-muted border border-transparent hover:bg-muted/80 focus-within:bg-background focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/20",
      },
      size: {
        sm: "min-h-8 text-xs py-1 px-2.5",
        md: "min-h-10 text-sm py-1.5 px-3",
        lg: "min-h-12 text-base py-2 px-3.5",
      },
      isInvalid: {
        true: "!border-rose-600 !ring-rose-600/20",
        false: "",
      },
    },
    defaultVariants: {
      variant: "bordered",
      size: "md",
      isInvalid: false,
    },
  }
);

export interface ComboBoxProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof comboBoxInputVariants> {
  options: ComboBoxOption[];
  /** Single selection value (when isMulti is false) */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;

  /** Multi-selection values (when isMulti is true) */
  values?: string[];
  defaultValues?: string[];
  onValuesChange?: (values: string[]) => void;

  /** Multi-select mode */
  isMulti?: boolean;

  placeholder?: string;
  label?: string;
  description?: string;
  errorMessage?: string;
  disabled?: boolean;
  emptyMessage?: string;
  isClearable?: boolean;
}

const ComboBox = React.forwardRef<HTMLDivElement, ComboBoxProps>(
  (
    {
      className,
      options = [],
      value,
      defaultValue,
      onValueChange,
      values,
      defaultValues,
      onValuesChange,
      isMulti = false,
      placeholder = "Select or search...",
      label,
      description,
      errorMessage,
      variant = "bordered",
      size = "md",
      isInvalid = false,
      disabled = false,
      emptyMessage = "No results found.",
      isClearable = true,
      ...props
    },
    ref
  ) => {
    const containerRef = React.useRef<HTMLDivElement | null>(null);
    const inputRef = React.useRef<HTMLInputElement | null>(null);

    // Controlled or uncontrolled state for single selection
    const [selectedSingle, setSelectedSingle] = React.useState<string>(defaultValue ?? "");
    const currentSingle = value !== undefined ? value : selectedSingle;

    // Controlled or uncontrolled state for multi selection
    const [selectedMulti, setSelectedMulti] = React.useState<string[]>(defaultValues ?? []);
    const currentMulti = values !== undefined ? values : selectedMulti;

    // Active single option label
    const activeSingleOption = options.find((opt) => opt.value === currentSingle);

    // Search query and open states
    const [isOpen, setIsOpen] = React.useState(false);
    const [searchQuery, setSearchQuery] = React.useState(
      !isMulti && activeSingleOption ? activeSingleOption.label : ""
    );

    // Sync input text when external single value changes
    React.useEffect(() => {
      if (!isMulti) {
        if (activeSingleOption) {
          setSearchQuery(activeSingleOption.label);
        } else if (!currentSingle) {
          setSearchQuery("");
        }
      }
    }, [currentSingle, activeSingleOption, isMulti]);

    // Handle outside click
    React.useEffect(() => {
      const handleOutsideClick = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          setIsOpen(false);
          if (!isMulti) {
            if (activeSingleOption) {
              setSearchQuery(activeSingleOption.label);
            } else {
              setSearchQuery("");
            }
          } else {
            setSearchQuery("");
          }
        }
      };

      document.addEventListener("mousedown", handleOutsideClick);
      return () => {
        document.removeEventListener("mousedown", handleOutsideClick);
      };
    }, [activeSingleOption, isMulti]);

    // Filtered options based on search query
    const filteredOptions = React.useMemo(() => {
      if (!searchQuery) {
        return options;
      }
      if (!isMulti && activeSingleOption && searchQuery === activeSingleOption.label) {
        return options;
      }
      return options.filter((opt) =>
        opt.label.toLowerCase().includes(searchQuery.toLowerCase().trim())
      );
    }, [options, searchQuery, activeSingleOption, isMulti]);

    const handleSelectOption = (opt: ComboBoxOption) => {
      if (opt.disabled) return;

      if (isMulti) {
        const isAlreadySelected = currentMulti.includes(opt.value);
        const newValues = isAlreadySelected
          ? currentMulti.filter((v) => v !== opt.value)
          : [...currentMulti, opt.value];

        if (values === undefined) {
          setSelectedMulti(newValues);
        }
        onValuesChange?.(newValues);
        setSearchQuery("");
        inputRef.current?.focus();
      } else {
        if (value === undefined) {
          setSelectedSingle(opt.value);
        }
        setSearchQuery(opt.label);
        onValueChange?.(opt.value);
        setIsOpen(false);
      }
    };

    const handleRemoveTag = (valToRemove: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (disabled) return;
      const newValues = currentMulti.filter((v) => v !== valToRemove);
      if (values === undefined) {
        setSelectedMulti(newValues);
      }
      onValuesChange?.(newValues);
      inputRef.current?.focus();
    };

    const handleClear = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (isMulti) {
        if (values === undefined) {
          setSelectedMulti([]);
        }
        onValuesChange?.([]);
      } else {
        if (value === undefined) {
          setSelectedSingle("");
        }
        onValueChange?.("");
      }
      setSearchQuery("");
      inputRef.current?.focus();
    };

    const hasSelection = isMulti ? currentMulti.length > 0 : Boolean(currentSingle || searchQuery);

    return (
      <div
        ref={(node) => {
          containerRef.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        className={cn("relative flex w-full flex-col gap-1.5", className)}
        {...props}
      >
        {/* Label */}
        {label && (
          <label className="text-foreground text-sm font-medium select-none">{label}</label>
        )}

        {/* Input Wrapper Box */}
        <div
          className={cn(
            "relative flex w-full cursor-text flex-wrap items-center gap-1.5 pr-16",
            comboBoxInputVariants({ variant, size, isInvalid }),
            disabled && "cursor-not-allowed opacity-50"
          )}
          onClick={() => {
            if (!disabled) {
              setIsOpen(true);
              inputRef.current?.focus();
            }
          }}
        >
          {/* Multi-Select Chips */}
          {isMulti &&
            currentMulti.map((val) => {
              const opt = options.find((o) => o.value === val);
              const label = opt ? opt.label : val;
              return (
                <span
                  key={val}
                  className="border-border/80 bg-accent text-accent-foreground inline-flex items-center gap-1 rounded-lg border px-2.5 py-0.5 text-xs font-medium transition-colors select-none"
                >
                  <span className="max-w-[120px] truncate">{label}</span>
                  {!disabled && (
                    <button
                      type="button"
                      tabIndex={-1}
                      onClick={(e) => handleRemoveTag(val, e)}
                      className="text-muted-foreground hover:bg-muted hover:text-foreground rounded-sm p-0.5 transition-colors"
                      aria-label={`Remove ${label}`}
                    >
                      <svg
                        className="h-3 w-3"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      >
                        <path d="M18 6 6 18" />
                        <path d="m6 6 12 12" />
                      </svg>
                    </button>
                  )}
                </span>
              );
            })}

          {/* Search Input */}
          <input
            ref={inputRef}
            type="text"
            value={searchQuery}
            placeholder={isMulti && currentMulti.length > 0 ? "" : placeholder}
            disabled={disabled}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              if (!isOpen) setIsOpen(true);
            }}
            onFocus={() => setIsOpen(true)}
            className="placeholder:text-muted-foreground min-w-[80px] flex-1 bg-transparent py-0.5 text-inherit outline-none"
          />

          {/* Action Buttons (Clear & Chevron) */}
          <div className="text-muted-foreground absolute top-1/2 right-3.5 flex -translate-y-1/2 items-center gap-1.5">
            {isClearable && hasSelection && !disabled && (
              <button
                type="button"
                onClick={handleClear}
                className="text-muted-foreground hover:bg-accent hover:text-foreground rounded-md p-1 transition-colors"
                aria-label="Clear selection"
              >
                <svg
                  className="h-3.5 w-3.5"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M18 6 6 18" />
                  <path d="m6 6 12 12" />
                </svg>
              </button>
            )}

            <button
              type="button"
              tabIndex={-1}
              disabled={disabled}
              onClick={(e) => {
                e.stopPropagation();
                if (!disabled) {
                  setIsOpen(!isOpen);
                  if (!isOpen) inputRef.current?.focus();
                }
              }}
              className="text-muted-foreground hover:text-foreground rounded-md p-1 transition-transform duration-200"
              aria-label="Toggle dropdown"
            >
              <svg
                className={cn("h-4 w-4 transition-transform duration-200", isOpen && "rotate-180")}
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="m6 9 6 6 6-6" />
              </svg>
            </button>
          </div>
        </div>

        {/* Floating Dropdown Overlay */}
        {isOpen && !disabled && (
          <div className="animate-in fade-in-0 zoom-in-95 border-border/80 bg-popover text-popover-foreground absolute top-full left-0 z-50 mt-2 max-h-60 w-full overflow-y-auto rounded-2xl border p-1.5 shadow-xl backdrop-blur-md duration-150">
            {filteredOptions.length > 0 ? (
              <ul className="space-y-0.5" role="listbox">
                {filteredOptions.map((opt) => {
                  const isSelected = isMulti
                    ? currentMulti.includes(opt.value)
                    : opt.value === currentSingle;

                  return (
                    <li
                      key={opt.value}
                      role="option"
                      aria-selected={isSelected}
                      onClick={() => handleSelectOption(opt)}
                      className={cn(
                        "flex cursor-pointer items-center justify-between rounded-xl px-3 py-2 text-sm transition-all duration-150 select-none",
                        isSelected
                          ? "bg-accent text-accent-foreground font-medium"
                          : "text-popover-foreground hover:bg-accent hover:text-accent-foreground",
                        opt.disabled && "pointer-events-none cursor-not-allowed opacity-40"
                      )}
                    >
                      <span className="truncate">{opt.label}</span>
                      {isSelected && (
                        <svg
                          className="text-foreground ml-2 h-4 w-4 shrink-0"
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2.5"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        >
                          <path d="M20 6 9 17l-5-5" />
                        </svg>
                      )}
                    </li>
                  );
                })}
              </ul>
            ) : (
              <div className="text-muted-foreground px-3 py-4 text-center text-xs select-none">
                {emptyMessage}
              </div>
            )}
          </div>
        )}

        {/* Description & Error Message */}
        {description && !errorMessage && (
          <span className="text-muted-foreground text-xs">{description}</span>
        )}
        {errorMessage && <span className="text-xs font-medium text-rose-600">{errorMessage}</span>}
      </div>
    );
  }
);

ComboBox.displayName = "ComboBox";

export { ComboBox, comboBoxInputVariants };

// packages/core/src/components/Command/Command.tsx
"use client";

import * as React from "react";
import { Search, X } from "lucide-react";
import { createPortal } from "react-dom";
import { cn } from "../utils/cn";

interface CommandContextValue {
  search: string;
  setSearch: (query: string) => void;
  selectedIndex: number;
  setSelectedIndex: (idx: number) => void;
  itemCount: number;
  registerItem: () => number;
  unregisterItem: () => void;
  executeItem: (idx: number) => void;
  registerItemCallback: (idx: number, onSelect?: () => void) => void;
}

const CommandContext = React.createContext<CommandContextValue>({
  search: "",
  setSearch: () => {},
  selectedIndex: 0,
  setSelectedIndex: () => {},
  itemCount: 0,
  registerItem: () => 0,
  unregisterItem: () => {},
  executeItem: () => {},
  registerItemCallback: () => {},
});

export const useCommandContext = () => React.useContext(CommandContext);

// ----------------------------------------------------
// Command Root
// ----------------------------------------------------

export interface CommandProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

export const Command = React.forwardRef<HTMLDivElement, CommandProps>(
  ({ className, children, ...props }, ref) => {
    const [search, setSearch] = React.useState("");
    const [selectedIndex, setSelectedIndex] = React.useState(0);
    const [itemCount, setItemCount] = React.useState(0);
    const callbacks = React.useRef<Map<number, () => void>>(new Map());

    const registerItem = React.useCallback(() => {
      let idx = 0;
      setItemCount((prev) => {
        idx = prev;
        return prev + 1;
      });
      return idx;
    }, []);

    const unregisterItem = React.useCallback(() => {
      setItemCount((prev) => Math.max(0, prev - 1));
    }, []);

    const registerItemCallback = React.useCallback((idx: number, onSelect?: () => void) => {
      if (onSelect) {
        callbacks.current.set(idx, onSelect);
      } else {
        callbacks.current.delete(idx);
      }
    }, []);

    const executeItem = React.useCallback((idx: number) => {
      const cb = callbacks.current.get(idx);
      cb?.();
    }, []);

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (itemCount === 0) return;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev + 1) % itemCount);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev - 1 + itemCount) % itemCount);
      } else if (e.key === "Enter") {
        e.preventDefault();
        executeItem(selectedIndex);
      }
    };

    return (
      <CommandContext.Provider
        value={{
          search,
          setSearch,
          selectedIndex,
          setSelectedIndex,
          itemCount,
          registerItem,
          unregisterItem,
          executeItem,
          registerItemCallback,
        }}
      >
        <div
          ref={ref}
          onKeyDown={handleKeyDown}
          className={cn(
            "flex h-full w-full flex-col overflow-hidden rounded-2xl bg-white text-zinc-900 dark:bg-zinc-900 dark:text-zinc-100",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </CommandContext.Provider>
    );
  }
);
Command.displayName = "Command";

// ----------------------------------------------------
// CommandDialog (Modal Container)
// ----------------------------------------------------

export interface CommandDialogProps {
  isOpen: boolean;
  onClose?: () => void;
  isDismissable?: boolean;
  children: React.ReactNode;
}

export const CommandDialog: React.FC<CommandDialogProps> = ({
  isOpen,
  onClose,
  isDismissable = true,
  children,
}) => {
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // Keyboard Escape & Global Cmd+K trigger
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isOpen && isDismissable) {
        onClose?.();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, isDismissable, onClose]);

  // Lock scroll
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  if (!isOpen || !mounted) return null;

  const content = (
    <div className="fixed inset-0 z-[100] flex items-start justify-center p-4 pt-16 sm:p-6 sm:pt-24">
      {/* Backdrop */}
      <div
        className="bg-background/80 animate-in fade-in-0 fixed inset-0 backdrop-blur-md transition-opacity duration-200"
        aria-hidden="true"
        onClick={() => {
          if (isDismissable) onClose?.();
        }}
      />

      {/* Modal Box */}
      <div className="animate-in fade-in-0 zoom-in-95 relative z-10 w-full max-w-xl overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-2xl transition-all duration-200 dark:border-zinc-800 dark:bg-zinc-900">
        <Command>{children}</Command>
      </div>
    </div>
  );

  return typeof document !== "undefined" ? createPortal(content, document.body) : null;
};

// ----------------------------------------------------
// CommandInput
// ----------------------------------------------------

export interface CommandInputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "onChange"
> {
  onValueChange?: (val: string) => void;
}

export const CommandInput = React.forwardRef<HTMLInputElement, CommandInputProps>(
  ({ className, placeholder = "Type a command or search...", onValueChange, ...props }, ref) => {
    const { search, setSearch, setSelectedIndex } = useCommandContext();

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setSearch(val);
      setSelectedIndex(0);
      onValueChange?.(val);
    };

    return (
      <div className="flex items-center border-b border-zinc-200 px-4 dark:border-zinc-800">
        <Search className="mr-2.5 h-4 w-4 shrink-0 text-zinc-400" />
        <input
          ref={ref}
          type="text"
          value={search}
          onChange={handleChange}
          placeholder={placeholder}
          className={cn(
            "flex h-12 w-full bg-transparent py-3 text-sm outline-none placeholder:text-zinc-400 disabled:cursor-not-allowed disabled:opacity-50 dark:placeholder:text-zinc-500",
            className
          )}
          {...props}
        />
        {search && (
          <button
            type="button"
            aria-label="Clear search"
            onClick={() => {
              setSearch("");
              onValueChange?.("");
            }}
            className="rounded p-1 text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}
      </div>
    );
  }
);
CommandInput.displayName = "CommandInput";

// ----------------------------------------------------
// CommandList
// ----------------------------------------------------

export interface CommandListProps extends React.HTMLAttributes<HTMLDivElement> {}

export const CommandList = React.forwardRef<HTMLDivElement, CommandListProps>(
  ({ className, children, ...props }, ref) => (
    <div
      ref={ref}
      role="listbox"
      className={cn("max-h-80 overflow-x-hidden overflow-y-auto p-2 text-left", className)}
      {...props}
    >
      {children}
    </div>
  )
);
CommandList.displayName = "CommandList";

// ----------------------------------------------------
// CommandEmpty
// ----------------------------------------------------

export interface CommandEmptyProps extends React.HTMLAttributes<HTMLDivElement> {}

export const CommandEmpty = React.forwardRef<HTMLDivElement, CommandEmptyProps>(
  ({ className, children = "No results found.", ...props }, ref) => {
    const { itemCount } = useCommandContext();
    if (itemCount > 0) return null;

    return (
      <div
        ref={ref}
        className={cn("py-6 text-center text-sm text-zinc-500 dark:text-zinc-400", className)}
        {...props}
      >
        {children}
      </div>
    );
  }
);
CommandEmpty.displayName = "CommandEmpty";

// ----------------------------------------------------
// CommandGroup
// ----------------------------------------------------

export interface CommandGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  heading?: React.ReactNode;
}

export const CommandGroup = React.forwardRef<HTMLDivElement, CommandGroupProps>(
  ({ className, heading, children, ...props }, ref) => (
    <div ref={ref} className={cn("text-foreground overflow-hidden p-1", className)} {...props}>
      {heading && (
        <div className="px-2 py-1.5 text-xs font-semibold text-zinc-500 dark:text-zinc-400">
          {heading}
        </div>
      )}
      <div className="space-y-0.5">{children}</div>
    </div>
  )
