"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

import { createPortal } from "react-dom";

export type DialogSize = "sm" | "md";
export type DialogSeverity = "default" | "danger";

interface DialogContextValue {
  isOpen: boolean;
  onClose?: () => void;
  size?: DialogSize;
  severity?: DialogSeverity;
}

const DialogContext = React.createContext<DialogContextValue>({
  isOpen: false,
});

const dialogPanelVariants = cva(
  "relative w-full overflow-hidden bg-background border border-border/80 shadow-2xl rounded-3xl p-6 sm:p-7 transition-all animate-in fade-in-0 zoom-in-95 duration-200 focus-visible:outline-none",
  {
    variants: {
      size: {
        sm: "max-w-sm",
        md: "max-w-lg",
      },
      severity: {
        default: "",
        danger: "border-t-4 border-t-destructive",
      },
    },
    defaultVariants: {
      size: "md",
      severity: "default",
    },
  }
);

export interface DialogProps {
  isOpen: boolean;
  onClose?: () => void;
  size?: DialogSize;
  severity?: DialogSeverity;
  isDismissable?: boolean;
  children: React.ReactNode;
}

const Dialog: React.FC<DialogProps> = ({
  isOpen,
  onClose,
  size = "md",
  severity = "default",
  isDismissable = true,
  children,
}) => {
  const [mounted, setMounted] = React.useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // ESC key to close
  React.useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isDismissable) {
        onClose?.();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, isDismissable, onClose]);

  // Prevent background scroll when dialog is open
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  if (!isOpen || !mounted) return null;

  const content = (
    <DialogContext.Provider value={{ isOpen, onClose, size, severity }}>
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
        {/* Backdrop */}
        <div
          className="animate-in fade-in-0 bg-background/80 fixed inset-0 backdrop-blur-md transition-opacity duration-200"
          aria-hidden="true"
          onClick={() => {
            if (isDismissable) onClose?.();
          }}
        />

        {/* Dialog Centered Content */}
        <div className="pointer-events-auto relative z-10 flex w-full items-center justify-center">
          {children}
        </div>
      </div>
    </DialogContext.Provider>
  );

  return createPortal(content, document.body);
};
Dialog.displayName = "Dialog";

export interface DialogContentProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof dialogPanelVariants> {}

const DialogContent = React.forwardRef<HTMLDivElement, DialogContentProps>(
  ({ className, size: propSize, severity: propSeverity, children, ...props }, ref) => {
    const context = React.useContext(DialogContext);
    const size = propSize ?? context.size ?? "md";
    const severity = propSeverity ?? context.severity ?? "default";

    return (
      <div
        ref={ref}
        role="dialog"
        aria-modal="true"
        className={cn(dialogPanelVariants({ size, severity }), className)}
        {...props}
      >
        {children}
      </div>
    );
  }
);
DialogContent.displayName = "DialogContent";

export interface DialogHeaderProps extends React.HTMLAttributes<HTMLDivElement> {}

const DialogHeader = React.forwardRef<HTMLDivElement, DialogHeaderProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={cn("mb-5 flex flex-col gap-1.5 text-left", className)} {...props}>
        {children}
      </div>
    );
  }
);
DialogHeader.displayName = "DialogHeader";

export interface DialogTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {}

const DialogTitle = React.forwardRef<HTMLHeadingElement, DialogTitleProps>(
  ({ className, children, ...props }, ref) => {
    const context = React.useContext(DialogContext);

    return (
      <h2
        ref={ref}
        className={cn(
          "text-foreground flex items-center gap-2 text-lg font-bold tracking-tight",
          context.severity === "danger" && "text-rose-600",
          className
        )}
        {...props}
      >
        {children}
      </h2>
    );
  }
);
DialogTitle.displayName = "DialogTitle";

export interface DialogDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement> {}

const DialogDescription = React.forwardRef<HTMLParagraphElement, DialogDescriptionProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <p
        ref={ref}
        className={cn("text-muted-foreground text-sm leading-normal", className)}
        {...props}
      >
        {children}
      </p>
    );
  }
);
DialogDescription.displayName = "DialogDescription";

export interface DialogFooterProps extends React.HTMLAttributes<HTMLDivElement> {}

const DialogFooter = React.forwardRef<HTMLDivElement, DialogFooterProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "mt-2 flex flex-col-reverse gap-2.5 pt-4 sm:flex-row sm:justify-end",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
DialogFooter.displayName = "DialogFooter";

export {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  dialogPanelVariants,
};

// packages/core/src/components/Divider/Divider.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type DividerOrientation = "horizontal" | "vertical";
export type DividerVariant = "solid" | "dashed";
export type DividerContentPosition = "left" | "center" | "right";

const dividerVariants = cva("shrink-0", {
  variants: {
    orientation: {
      horizontal: "w-full",
      vertical: "h-full min-h-[1.25rem] w-[1px] self-stretch",
    },
    variant: {
      solid: "",
      dashed: "",
    },
  },
  defaultVariants: {
    orientation: "horizontal",
    variant: "solid",
  },
});

export interface DividerProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof dividerVariants> {
  orientation?: DividerOrientation;
  variant?: DividerVariant;
  contentPosition?: DividerContentPosition;
  children?: React.ReactNode;
}

const Divider = React.forwardRef<HTMLDivElement, DividerProps>(
  (
    {
      className,
      orientation = "horizontal",
      variant = "solid",
      contentPosition = "center",
      children,
      ...props
    },
    ref
  ) => {
    // If divider has children/content (only applicable in horizontal layout)
    if (children && orientation === "horizontal") {
      const isLeft = contentPosition === "left";
      const isRight = contentPosition === "right";

      const lineStyle =
        variant === "dashed"
          ? "border-b border-dashed border-zinc-200 dark:border-zinc-800"
          : "h-[1px] bg-zinc-200/70 dark:bg-zinc-800/70";

      return (
        <div
          ref={ref}
          role="separator"
          aria-orientation="horizontal"
          className={cn("my-3 flex w-full items-center select-none", className)}
          {...props}
        >
          {/* Left line */}
          <div className={cn(lineStyle, isLeft ? "w-8 shrink-0" : isRight ? "flex-1" : "flex-1")} />

          {/* Content */}
          <span className="shrink-0 px-3 text-xs font-medium tracking-wider text-zinc-400 uppercase dark:text-zinc-500">
            {children}
          </span>

          {/* Right line */}
          <div className={cn(lineStyle, isRight ? "w-8 shrink-0" : isLeft ? "flex-1" : "flex-1")} />
        </div>
      );
    }

    // Standard simple divider
    if (orientation === "vertical") {
      return (
        <div
          ref={ref}
          role="separator"
          aria-orientation="vertical"
          className={cn(
            dividerVariants({ orientation, variant }),
            variant === "dashed"
              ? "border-l border-dashed border-zinc-200 bg-transparent dark:border-zinc-800"
              : "bg-zinc-200/70 dark:bg-zinc-800/70",
            className
          )}
          {...props}
        />
      );
    }

    return (
      <div
        ref={ref}
        role="separator"
        aria-orientation="horizontal"
        className={cn(
          dividerVariants({ orientation, variant }),
          variant === "dashed"
            ? "my-3 h-0 border-b border-dashed border-zinc-200 bg-transparent dark:border-zinc-800"
            : "my-3 h-[1px] bg-zinc-200/70 dark:bg-zinc-800/70",
          className
        )}
        {...props}
      />
    );
  }
);

Divider.displayName = "Divider";

export { Divider, dividerVariants };

