          "bg-white dark:bg-[#13121a] border border-brand-200/60 dark:border-brand-900/50 shadow-[inset_0_1px_0_0_rgba(157,88,190,0.15)] text-zinc-900 dark:text-zinc-100",
      },
    },
    defaultVariants: {
      padding: "md",
      variant: "default",
    },
  }
