export interface KineticButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof kineticButtonVariants> {
  href?: string;
  target?: string;
  rel?: string;
  showArrow?: boolean;
  arrowPosition?: "right" | "left";
  icon?: React.ReactNode;
  classNames?: {
