      radius: "xl",
    },
  }
);

export interface PaginationProps extends Omit<React.HTMLAttributes<HTMLElement>, "onChange"> {
  /**
   * Total number of pages.
   */
  total: number;
  /**
   * Current active page (1-indexed).
   */
  page?: number;
  /**
   * Initial page when uncontrolled.
   * @default 1
   */
  defaultPage?: number;
  /**
   * Number of sibling pages shown before and after the current page.
   * @default 1
   */
  siblings?: number;
  /**
   * Number of boundary pages shown at the start and end.
   * @default 1
   */
  boundaries?: number;
  /**
   * Visual styling variant.
   * @default "solid"
   */
  variant?: PaginationVariant;
  /**
   * Brand theme color for active item and highlights.
   * @default "primary"
   */
  color?: PaginationColor;
  /**
   * Sizing scale for buttons.
   * @default "md"
   */
  size?: PaginationSize;
  /**
   * Border radius tokens for buttons.
   * @default "xl"
   */
  radius?: PaginationRadius;
  /**
   * Whether to show Next and Prev arrow buttons.
   * @default true
   */
  showControls?: boolean;
  /**
   * Custom label or icon for Prev button.
   */
  prevContent?: React.ReactNode;
  /**
   * Custom label or icon for Next button.
   */
  nextContent?: React.ReactNode;
  /**
   * Whether the pagination controls are disabled.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Callback fired when active page changes.
   */
  onChange?: (page: number) => void;
}

export type PaginationItemValue = number | "dots-left" | "dots-right";

/**
 * Generate pagination page items with smart logarithmic/dynamic ellipsis truncation
 */
function usePaginationRange({
  total,
  page,
  siblings = 1,
  boundaries = 1,
}: {
  total: number;
  page: number;
  siblings: number;
  boundaries: number;
}): PaginationItemValue[] {
  return React.useMemo(() => {
    const totalPageNumbers = siblings * 2 + 3 + boundaries * 2;

    if (total <= totalPageNumbers) {
      return Array.from({ length: total }, (_, i) => i + 1);
    }

    const leftSiblingIndex = Math.max(page - siblings, boundaries + 1);
    const rightSiblingIndex = Math.min(page + siblings, total - boundaries);

    const shouldShowLeftDots = leftSiblingIndex > boundaries + 2;
    const shouldShowRightDots = rightSiblingIndex < total - (boundaries + 1);

    const startPages = Array.from({ length: boundaries }, (_, i) => i + 1);
    const endPages = Array.from({ length: boundaries }, (_, i) => total - boundaries + 1 + i);

    if (!shouldShowLeftDots && shouldShowRightDots) {
      const leftItemCount = siblings * 2 + boundaries + 2;
      const leftRange = Array.from({ length: leftItemCount }, (_, i) => i + 1);
      return [...leftRange, "dots-right", ...endPages];
    }

    if (shouldShowLeftDots && !shouldShowRightDots) {
      const rightItemCount = siblings * 2 + boundaries + 2;
      const rightRange = Array.from(
        { length: rightItemCount },
        (_, i) => total - rightItemCount + 1 + i
      );
      return [...startPages, "dots-left", ...rightRange];
    }

    if (shouldShowLeftDots && shouldShowRightDots) {
      const middleRange = Array.from(
        { length: rightSiblingIndex - leftSiblingIndex + 1 },
        (_, i) => leftSiblingIndex + i
      );
      return [...startPages, "dots-left", ...middleRange, "dots-right", ...endPages];
    }

    return Array.from({ length: total }, (_, i) => i + 1);
  }, [total, page, siblings, boundaries]);
}

/**
 * Pagination Component
 * Elegant, responsive page navigation with smart ellipsis calculation, multiple variants, and colors.
 */
export const Pagination = React.forwardRef<HTMLElement, PaginationProps>(
  (
    {
      total,
      page: controlledPage,
      defaultPage = 1,
      siblings = 1,
      boundaries = 1,
      variant = "solid",
      color = "primary",
      size = "md",
      radius = "xl",
      showControls = true,
      prevContent,
      nextContent,
      isDisabled = false,
      onChange,
      className,
      ...props
    },
    ref
  ) => {
    const [uncontrolledPage, setUncontrolledPage] = React.useState(defaultPage);
    const isControlled = controlledPage !== undefined;
    const activePage = Math.min(
      Math.max(1, isControlled ? controlledPage : uncontrolledPage),
      Math.max(1, total)
    );

    const handlePageChange = (newPage: number) => {
      if (isDisabled) return;
      if (newPage < 1 || newPage > total || newPage === activePage) return;

      if (!isControlled) {
        setUncontrolledPage(newPage);
      }
      onChange?.(newPage);
    };

    const paginationRange = usePaginationRange({
      total: Math.max(1, total),
      page: activePage,
      siblings,
      boundaries,
    });

    // Color & Variant styles for active item
    const getActiveStyles = () => {
      switch (variant) {
        case "solid":
          switch (color) {
            case "primary":
              return "bg-primary text-primary-foreground shadow-xs hover:bg-primary-hover focus-visible:ring-primary";
            case "success":
              return "bg-emerald-600 text-white shadow-xs hover:bg-emerald-700 focus-visible:ring-emerald-600 dark:bg-emerald-500 dark:hover:bg-emerald-600";
            case "danger":
              return "bg-rose-600 text-white shadow-xs hover:bg-rose-700 focus-visible:ring-rose-600 dark:bg-rose-500 dark:hover:bg-rose-600";
            case "dark":
              return "bg-zinc-900 text-white shadow-xs hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-950 dark:hover:bg-white focus-visible:ring-zinc-900 dark:focus-visible:ring-zinc-100";
            case "zinc":
            default:
              return "bg-zinc-800 text-white shadow-xs hover:bg-zinc-700 dark:bg-zinc-200 dark:text-zinc-900 dark:hover:bg-white focus-visible:ring-zinc-600";
          }
        case "bordered":
          switch (color) {
            case "primary":
              return "border-2 border-primary-600 text-primary-700 bg-primary-50 focus-visible:ring-primary dark:border-primary-500 dark:text-primary-400 dark:bg-primary-500/15";
            case "success":
              return "border-2 border-emerald-600 text-emerald-700 bg-emerald-50 focus-visible:ring-emerald-600 dark:border-emerald-400 dark:text-emerald-400 dark:bg-emerald-500/15";
            case "danger":
              return "border-2 border-rose-600 text-rose-700 bg-rose-50 focus-visible:ring-rose-600 dark:border-rose-400 dark:text-rose-400 dark:bg-rose-500/15";
            case "dark":
              return "border-2 border-zinc-900 text-zinc-900 bg-zinc-100/60 dark:border-zinc-100 dark:text-zinc-100 dark:bg-zinc-800/60 focus-visible:ring-zinc-900";
            case "zinc":
            default:
              return "border-2 border-zinc-700 text-zinc-800 bg-zinc-100/60 dark:border-zinc-300 dark:text-zinc-200 dark:bg-zinc-800/60 focus-visible:ring-zinc-600";
          }
        case "flat":
          switch (color) {
            case "primary":
              return "bg-primary-50 text-primary-700 hover:bg-primary-100 focus-visible:ring-primary-600 dark:bg-primary-500/15 dark:text-primary-400 dark:hover:bg-primary-500/25";
            case "success":
              return "bg-emerald-50 text-emerald-700 hover:bg-emerald-100 focus-visible:ring-emerald-600 dark:bg-emerald-500/15 dark:text-emerald-400 dark:hover:bg-emerald-500/25";
            case "danger":
              return "bg-rose-50 text-rose-700 hover:bg-rose-100 focus-visible:ring-rose-600 dark:bg-rose-500/15 dark:text-rose-400 dark:hover:bg-rose-500/25";
            case "dark":
              return "bg-zinc-200 text-zinc-900 dark:bg-zinc-800 dark:text-zinc-100 hover:bg-zinc-300 dark:hover:bg-zinc-700 focus-visible:ring-zinc-900";
            case "zinc":
            default:
              return "bg-zinc-200 text-zinc-800 dark:bg-zinc-800 dark:text-zinc-200 hover:bg-zinc-300 dark:hover:bg-zinc-700 focus-visible:ring-zinc-600";
          }
        case "light":
        default:
          switch (color) {
            case "primary":
              return "text-primary-700 font-bold bg-primary-50 hover:bg-primary-100 focus-visible:ring-primary-600 dark:text-primary-400 dark:bg-primary-500/15 dark:hover:bg-primary-500/25";
            case "success":
              return "text-emerald-700 font-bold bg-emerald-50 hover:bg-emerald-100 focus-visible:ring-emerald-600 dark:text-emerald-400 dark:bg-emerald-500/15 dark:hover:bg-emerald-500/25";
            case "danger":
              return "text-rose-700 font-bold bg-rose-50 hover:bg-rose-100 focus-visible:ring-rose-600 dark:text-rose-400 dark:bg-rose-500/15 dark:hover:bg-rose-500/25";
            case "dark":
              return "text-zinc-950 font-bold bg-zinc-100 dark:text-zinc-50 dark:bg-zinc-800 hover:bg-zinc-200 dark:hover:bg-zinc-700 focus-visible:ring-zinc-900";
            case "zinc":
            default:
              return "text-zinc-800 font-bold bg-zinc-100 dark:text-zinc-200 dark:bg-zinc-800 hover:bg-zinc-200 dark:hover:bg-zinc-700 focus-visible:ring-zinc-600";
          }
      }
    };

    // Inactive regular item styles
    const inactiveStyles =
      "text-zinc-600 dark:text-zinc-400 bg-transparent hover:bg-zinc-100 dark:hover:bg-zinc-800/80 hover:text-zinc-900 dark:hover:text-zinc-100 focus-visible:ring-zinc-400 dark:focus-visible:ring-zinc-600";

    const isFirstPage = activePage <= 1;
    const isLastPage = activePage >= total;

    return (
      <nav
        ref={ref}
        role="navigation"
        aria-label="Pagination Navigation"
        className={cn(
          "inline-flex items-center gap-1.5 rounded-2xl p-1",
          isDisabled && "pointer-events-none opacity-50",
          className
        )}
        {...props}
      >
        {/* Previous Button */}
        {showControls && (
          <button
            type="button"
            aria-label="Previous page"
            disabled={isDisabled || isFirstPage}
            onClick={() => handlePageChange(activePage - 1)}
            className={cn(
              paginationItemVariants({ size, radius }),
              "border border-zinc-200 bg-white text-zinc-700 shadow-xs hover:bg-zinc-50 hover:text-zinc-950 focus-visible:ring-zinc-500 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-300 dark:hover:bg-zinc-800/80 dark:hover:text-white dark:focus-visible:ring-offset-zinc-950"
            )}
          >
            {prevContent ?? (
              <span className="flex items-center gap-1">
                <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M15 19l-7-7 7-7"
                  />
                </svg>
                <span className="hidden sm:inline">Prev</span>
              </span>
            )}
          </button>
        )}

        {/* Page Items & Ellipsis */}
        {paginationRange.map((item, index) => {
          if (item === "dots-left" || item === "dots-right") {
            const jumpTarget =
              item === "dots-left"
                ? Math.max(1, activePage - siblings * 2 - 1)
                : Math.min(total, activePage + siblings * 2 + 1);

            return (
              <button
                key={`dots-${index}-${item}`}
                type="button"
                title={`Jump to page ${jumpTarget}`}
                aria-label={`Jump ${item === "dots-left" ? "backward" : "forward"}`}
                disabled={isDisabled}
                onClick={() => handlePageChange(jumpTarget)}
                className={cn(
                  paginationItemVariants({ size, radius }),
                  "group text-zinc-400 hover:bg-zinc-100 hover:text-zinc-700 dark:text-zinc-500 dark:hover:bg-zinc-800/60 dark:hover:text-zinc-300"
                )}
              >
                <span className="text-xs tracking-widest group-hover:hidden">•••</span>
                <span className="hidden text-xs font-semibold group-hover:inline">
                  {item === "dots-left" ? "«" : "»"}
                </span>
              </button>
            );
          }

          const isActive = item === activePage;

          return (
            <button
              key={`page-${item}`}
              type="button"
              aria-current={isActive ? "page" : undefined}
              aria-label={`Page ${item}`}
              disabled={isDisabled}
              onClick={() => handlePageChange(item as number)}
              className={cn(
                paginationItemVariants({ size, radius }),
                isActive ? getActiveStyles() : inactiveStyles
              )}
            >
              {item}
            </button>
          );
        })}

        {/* Next Button */}
        {showControls && (
          <button
            type="button"
            aria-label="Next page"
            disabled={isDisabled || isLastPage}
            onClick={() => handlePageChange(activePage + 1)}
            className={cn(
              paginationItemVariants({ size, radius }),
              "border border-zinc-200 bg-white text-zinc-700 shadow-xs hover:bg-zinc-50 hover:text-zinc-950 focus-visible:ring-zinc-500 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-300 dark:hover:bg-zinc-800/80 dark:hover:text-white dark:focus-visible:ring-offset-zinc-950"
            )}
          >
            {nextContent ?? (
              <span className="flex items-center gap-1">
                <span className="hidden sm:inline">Next</span>
                <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 5l7 7-7 7"
                  />
                </svg>
              </span>
            )}
          </button>
        )}
      </nav>
    );
  }
);

Pagination.displayName = "Pagination";

"use client";

import React, { useMemo } from "react";
import {
  PieChart as RechartsPieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Label,
} from "recharts";
import { ChartTooltip } from "../ChartTooltip/ChartTooltip";
import { cn } from "../utils/cn";
import { motion } from "framer-motion";

export interface PieChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd" | "ref"
> {
  /**
   * Array of objects containing the data to render.
   */
  data: any[];
  /**
   * The key in the data objects to map to the values.
   */
  category?: string;
  /**
   * Array of keys for rendering nested donut charts.
   */
  categories?: string[];
  /**
   * The key in the data objects to map to the name/label.
   */
  index: string;
  /**
   * Array of colors to use for the pie slices.
   */
  colors?: string[];
  /**
   * Variant of the pie chart. "pie" is solid, "donut" has a hole.
   */
  variant?: "pie" | "donut";
  /**
   * Whether to display the tooltip on hover.
   */
  showTooltip?: boolean;
  /**
   * Whether to display the chart legend.
   */
  showLegend?: boolean;
  /**
   * Custom component to render the tooltip.
   */
  customTooltip?: React.ReactElement | ((props: any) => React.ReactNode);
  children?: React.ReactNode;
  /**
   * Function to format the values on the Tooltip.
   */
  valueFormatter?: (value: number) => string;
  /**
   * Custom content to render in the center of the donut chart.
   */
  donutContent?: React.ReactNode;
  /**
   * Inner radius of the pie. If not provided, it is automatically calculated for "donut" variant.
   */
  innerRadius?: number | string;
  /**
   * Outer radius of the pie.
   */
  outerRadius?: number | string;
  /**
   * Whether to display labels on the pie slices.
   */
  showLabel?: boolean;
}

const defaultColors = [
  "var(--color-primary-500, #3b82f6)",
  "var(--color-success-500, #22c55e)",
  "var(--color-warning-500, #eab308)",
  "var(--color-danger-500, #ef4444)",
  "var(--color-secondary-500, #a855f7)",
  "var(--color-info-500, #0ea5e9)",
];

export const PieChart = React.forwardRef<HTMLDivElement, PieChartProps>(
  (
    {
      data = [],
      category,
      categories,
      index,
      colors = defaultColors,
      variant = "pie",
      showTooltip = true,
      showLegend = true,
      customTooltip,
      children,
      valueFormatter = (value: number) => value.toString(),
      donutContent,
      innerRadius,
      outerRadius,
      showLabel = false,
      className,
      ...props
    },
    ref
  ) => {
    // Determine the active categories array
    const activeCategories = useMemo(() => {
      if (categories && categories.length > 0) return categories;
      if (category) return [category];
      return [];
    }, [category, categories]);

    // Handle radii for nested charts or single charts
    const getRadii = (idx: number, total: number) => {
      const isDonut = variant === "donut" || total > 1; // Nested pies force donut behavior implicitly

      if (total === 1) {
        return {
          innerRadius: innerRadius ?? (isDonut ? "60%" : 0),
          outerRadius: outerRadius ?? "80%",
        };
      }

      // Logic for nested rings
      // Divide the available radius equally among the rings
      const availableRadius = 80; // use max 80%
      const step = availableRadius / total;
      const ringOuter = step * (idx + 1);
      const ringInner = isDonut ? step * idx + (idx === 0 ? 30 : 0) : step * idx; // Adjust inner for the first ring if donut

      return {
        innerRadius: `${ringInner}%`,
        outerRadius: `${ringOuter}%`,
      };
    };

    return (
      <motion.div
        ref={ref}
        className={cn("h-64 w-full sm:h-72", className)}
        {...props}
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <RechartsPieChart>
            {showTooltip && (
              <Tooltip
                content={
                  customTooltip
                    ? (customTooltip as any)
                    : (props) => (
                        <ChartTooltip {...(props as any)} valueFormatter={valueFormatter} />
                      )
                }
                cursor={{ fill: "var(--color-zinc-100, #f4f4f5)", opacity: 0.2 }}
              />
            )}

            {showLegend && (
              <Legend
                verticalAlign="bottom"
                height={36}
                iconType="circle"
                formatter={(value) => (
                  <span className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
                    {value}
                  </span>
                )}
              />
            )}

            {activeCategories.map((cat, idx) => {
              const { innerRadius: rInner, outerRadius: rOuter } = getRadii(
                idx,
                activeCategories.length
              );

              return (
                <Pie
                  key={cat}
                  data={data}
                  dataKey={cat}
                  nameKey={index}
                  cx="50%"
                  cy="50%"
                  innerRadius={rInner}
                  outerRadius={rOuter}
                  stroke="none"
                  label={
                    showLabel
                      ? {
                          fill: "var(--color-zinc-700, #3f3f46)",
                          fontSize: 12,
                          fontWeight: 500,
                        }
                      : false
                  }
                >
                  {data.map((entry, dataIdx) => {
                    // For nested pies, we might want to adjust colors to avoid them looking exactly the same.
                    // If total > 1, we offset the color index or modify opacity (not natively supported by simple Cell fill without parsing).
                    // For simplicity, we just loop through the provided colors array.
                    const colorOffset = idx * 2; // Arbitrary shift for outer rings
                    const fill = colors[(dataIdx + colorOffset) % colors.length];
                    return <Cell key={`cell-${dataIdx}`} fill={fill} />;
                  })}
                  {donutContent && idx === 0 && variant === "donut" && (
                    <Label
                      content={(props: any) => {
                        const { viewBox } = props;
                        const cxVal = viewBox?.cx ?? props.cx ?? "50%";
                        const cyVal = viewBox?.cy ?? props.cy ?? "50%";
                        return (
                          <foreignObject
                            x={cxVal}
                            y={cyVal}
                            width={1}
                            height={1}
                            style={{ pointerEvents: "none", overflow: "visible" }}
                          >
                            <div
                              className="pointer-events-none flex items-center justify-center"
                              style={{ width: 0, height: 0, overflow: "visible" }}
                            >
                              <div
                                style={{ width: "max-content", height: "max-content" }}
                                className="flex flex-col items-center justify-center"
                              >
                                {donutContent}
                              </div>
                            </div>
                          </foreignObject>
                        );
                      }}
                      position="center"
                    />
                  )}
                </Pie>
              );
            })}
            {children}
          </RechartsPieChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

PieChart.displayName = "PieChart";

// packages/core/src/components/Popover/Popover.tsx
"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type PopoverPlacement =
  | "top"
  | "top-start"
  | "top-end"
  | "bottom"
  | "bottom-start"
  | "bottom-end"
  | "left"
  | "left-start"
  | "left-end"
  | "right"
  | "right-start"
  | "right-end";

interface PopoverContextValue {
  isOpen: boolean;
  setIsOpen: React.Dispatch<React.SetStateAction<boolean>>;
  close: () => void;
  placement: PopoverPlacement;
}

const PopoverContext = React.createContext<PopoverContextValue>({
  isOpen: false,
  setIsOpen: () => {},
  close: () => {},
  placement: "bottom",
});

export const usePopoverContext = () => React.useContext(PopoverContext);

// ----------------------------------------------------
// Popover Root
// ----------------------------------------------------

export interface PopoverProps extends React.HTMLAttributes<HTMLDivElement> {
  placement?: PopoverPlacement;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  children: React.ReactNode;
}

export const Popover = React.forwardRef<HTMLDivElement, PopoverProps>(
  (
    {
      className,
      placement = "bottom",
      isOpen: propIsOpen,
      defaultOpen = false,
      onOpenChange,
      children,
      ...props
    },
    ref
  ) => {
    const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
    const containerRef = React.useRef<HTMLDivElement | null>(null);

    const isControlled = propIsOpen !== undefined;
    const isOpen = isControlled ? propIsOpen : uncontrolledOpen;

    const setIsOpen = React.useCallback(
      (value: React.SetStateAction<boolean>) => {
        const nextValue = typeof value === "function" ? value(isOpen) : value;
        if (!isControlled) {
          setUncontrolledOpen(nextValue);
        }
        onOpenChange?.(nextValue);
      },
      [isControlled, isOpen, onOpenChange]
    );

    const close = React.useCallback(() => {
      setIsOpen(false);
    }, [setIsOpen]);

    // Click outside listener
    React.useEffect(() => {
      if (!isOpen) return;

      const handleClickOutside = (e: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
          close();
        }
      };

      const handleEscape = (e: KeyboardEvent) => {
        if (e.key === "Escape") {
          close();
        }
      };

      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscape);
      return () => {
        document.removeEventListener("mousedown", handleClickOutside);
        document.removeEventListener("keydown", handleEscape);
      };
    }, [isOpen, close]);

    return (
      <PopoverContext.Provider value={{ isOpen, setIsOpen, close, placement }}>
        <div
          ref={(node) => {
            containerRef.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          className={cn("relative inline-block text-left", className)}
          {...props}
        >
          {children}
        </div>
      </PopoverContext.Provider>
    );
  }
);
Popover.displayName = "Popover";

// ----------------------------------------------------
// PopoverTrigger
// ----------------------------------------------------

export interface PopoverTriggerProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

export const PopoverTrigger = React.forwardRef<HTMLDivElement, PopoverTriggerProps>(
  ({ className, children, onClick, ...props }, ref) => {
    const { isOpen, setIsOpen } = usePopoverContext();

    return (
      <div
        ref={ref}
        className={cn("inline-flex cursor-pointer items-center select-none", className)}
        onClick={(e) => {
