"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type RadioColor = "default" | "primary" | "success" | "warning" | "danger";
export type RadioSize = "sm" | "md" | "lg";

export interface RadioGroupContextValue {
  name: string;
  value?: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  size?: RadioSize;
  color?: RadioColor;
  isDisabled?: boolean;
  isInvalid?: boolean;
  isReadOnly?: boolean;
}

export const RadioGroupContext = React.createContext<RadioGroupContextValue | null>(null);

export function useRadioGroupContext() {
  return React.useContext(RadioGroupContext);
}

export const radioCircleVariants = cva(
  "shrink-0 rounded-full border flex items-center justify-center transition-all duration-150 ease-out",
  {
    variants: {
      size: {
        sm: "h-4 w-4",
        md: "h-5 w-5",
        lg: "h-6 w-6",
      },
      color: {
        default: "",
        primary: "",
        success: "",
        warning: "",
        danger: "",
      },
      isChecked: {
        true: "",
        false:
          "bg-white dark:bg-zinc-900 border-zinc-300 dark:border-zinc-700 hover:border-zinc-400 dark:hover:border-zinc-600",
      },
      isInvalid: {
        true: "!border-rose-500 dark:!border-rose-400",
        false: "",
      },
    },
    compoundVariants: [
      {
        isChecked: true,
        color: "default",
        className: "bg-zinc-900 dark:bg-zinc-100 border-zinc-900 dark:border-zinc-100",
      },
      {
        isChecked: true,
        color: "primary",
        className: "bg-primary border-primary text-primary-foreground",
      },
      {
        isChecked: true,
        color: "success",
        className:
          "bg-emerald-600 border-emerald-600 text-white dark:bg-emerald-500 dark:border-emerald-500",
      },
      {
        isChecked: true,
        color: "warning",
        className:
          "bg-amber-500 border-amber-500 text-zinc-950 dark:bg-amber-400 dark:border-amber-400",
      },
      {
        isChecked: true,
        color: "danger",
        className: "bg-rose-600 border-rose-600 text-white dark:bg-rose-500 dark:border-rose-500",
      },
    ],
    defaultVariants: {
      size: "md",
      color: "primary",
      isChecked: false,
      isInvalid: false,
    },
  }
);

export const radioDotVariants = cva("rounded-full transition-transform duration-150 ease-out", {
  variants: {
    size: {
      sm: "h-1.5 w-1.5",
      md: "h-2 w-2",
      lg: "h-2.5 w-2.5",
    },
