"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type SliderColor = "primary" | "success" | "danger" | "warning";
export type SliderSize = "sm" | "md" | "lg";

const trackVariants = cva(
  "relative w-full rounded-full bg-zinc-200 dark:bg-zinc-800 cursor-pointer select-none transition-colors",
  {
    variants: {
      size: {
        sm: "h-1.5",
        md: "h-2.5",
        lg: "h-3.5",
      },
    },
    defaultVariants: {
      size: "md",
    },
  }
);

const rangeVariants = cva("absolute h-full rounded-full transition-all duration-75", {
  variants: {
    color: {
      primary: "bg-primary",
      success: "bg-emerald-600 dark:bg-emerald-500",
      danger: "bg-rose-600 dark:bg-rose-500",
      warning: "bg-amber-500 dark:bg-amber-400",
    },
  },
  defaultVariants: {
    color: "primary",
  },
});

const thumbVariants = cva(
  "absolute top-1/2 -translate-y-1/2 -translate-x-1/2 rounded-full border-2 border-white bg-white shadow-md transition-transform focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 active:scale-110 cursor-grab active:cursor-grabbing dark:border-zinc-900",
  {
    variants: {
      size: {
        sm: "h-4 w-4",
        md: "h-5 w-5",
        lg: "h-6 w-6",
      },
      color: {
        primary: "focus-visible:ring-primary",
        success: "focus-visible:ring-emerald-500",
        danger: "focus-visible:ring-rose-500",
        warning: "focus-visible:ring-amber-500",
      },
    },
    defaultVariants: {
      size: "md",
      color: "primary",
    },
  }
);

export interface SliderProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  label?: React.ReactNode;
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  color?: SliderColor;
  size?: SliderSize;
  isDisabled?: boolean;
  disabled?: boolean;
  showValue?: boolean;
  formatValue?: (val: number) => string;
  onChange?: (val: number) => void;
  onChangeEnd?: (val: number) => void;
}

export const Slider = React.forwardRef<HTMLDivElement, SliderProps>(
  (
    {
      className,
      label,
      value: propValue,
      defaultValue = 0,
      min = 0,
      max = 100,
      step = 1,
      color = "primary",
      size = "md",
      isDisabled: propIsDisabled,
      disabled = false,
      showValue = false,
      formatValue = (v) => String(v),
      onChange,
      onChangeEnd,
      ...props
    },
    ref
  ) => {
    const isActuallyDisabled = disabled || Boolean(propIsDisabled);

    const [uncontrolledVal, setUncontrolledVal] = React.useState<number>(defaultValue);
    const isControlled = propValue !== undefined;
    const currentVal = isControlled ? propValue : uncontrolledVal;

    // Clamp value
    const clampedVal = Math.min(Math.max(currentVal, min), max);
    const percentage = ((clampedVal - min) / (max - min)) * 100;

    const trackRef = React.useRef<HTMLDivElement | null>(null);

    const updateValue = React.useCallback(
      (newVal: number) => {
        if (isActuallyDisabled) return;
        const steppedVal = Math.round((newVal - min) / step) * step + min;
        const finalVal = Math.min(Math.max(steppedVal, min), max);

        if (!isControlled) {
          setUncontrolledVal(finalVal);
        }
        onChange?.(finalVal);
      },
      [isActuallyDisabled, min, max, step, isControlled, onChange]
    );

    const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
      if (isActuallyDisabled || !trackRef.current) return;
      const rect = trackRef.current.getBoundingClientRect();
      const pos = (e.clientX - rect.left) / rect.width;
      const newVal = min + pos * (max - min);
      updateValue(newVal);

      const onPointerMove = (moveEvent: PointerEvent) => {
        const movePos = (moveEvent.clientX - rect.left) / rect.width;
        const moveVal = min + movePos * (max - min);
        updateValue(moveVal);
      };

      const onPointerUp = () => {
        document.removeEventListener("pointermove", onPointerMove);
        document.removeEventListener("pointerup", onPointerUp);
        onChangeEnd?.(clampedVal);
      };

      document.addEventListener("pointermove", onPointerMove);
      document.addEventListener("pointerup", onPointerUp);
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (isActuallyDisabled) return;
      let next: number;
      if (e.key === "ArrowRight" || e.key === "ArrowUp") {
        next = Math.min(clampedVal + step, max);
      } else if (e.key === "ArrowLeft" || e.key === "ArrowDown") {
        next = Math.max(clampedVal - step, min);
      } else if (e.key === "Home") {
        next = min;
      } else if (e.key === "End") {
        next = max;
      } else {
        return;
      }
      e.preventDefault();
      updateValue(next);
      onChangeEnd?.(next);
    };

    return (
      <div
        ref={ref}
        className={cn(
          "flex w-full flex-col gap-2 select-none",
          isActuallyDisabled && "pointer-events-none cursor-not-allowed opacity-50",
          className
        )}
        {...props}
      >
        {(label || showValue) && (
          <div className="text-foreground flex items-center justify-between text-xs font-semibold">
            {label && <span>{label}</span>}
            {showValue && (
              <span className="text-muted-foreground font-mono">{formatValue(clampedVal)}</span>
            )}
          </div>
        )}

        <div
          ref={trackRef}
          onPointerDown={handlePointerDown}
          className={cn(trackVariants({ size }))}
        >
          {/* Active Range Fill */}
          <div className={cn(rangeVariants({ color }))} style={{ width: `${percentage}%` }} />

          {/* Draggable & Focusable Thumb */}
          <div
            role="slider"
            tabIndex={isActuallyDisabled ? -1 : 0}
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuenow={clampedVal}
            aria-disabled={isActuallyDisabled}
            onKeyDown={handleKeyDown}
            className={cn(thumbVariants({ size, color }))}
            style={{ left: `${percentage}%` }}
          />
        </div>
      </div>
    );
  }
);

Slider.displayName = "Slider";

// packages/core/src/components/Slot/Slot.tsx
import * as React from "react";
import { cn } from "../utils/cn";

export interface SlotProps extends React.HTMLAttributes<HTMLElement> {
  children?: React.ReactNode;
}

export const Slot = React.forwardRef<HTMLElement, SlotProps>((props, forwardedRef) => {
  const { children, className, style, ...slotProps } = props;

  if (React.isValidElement(children)) {
    const child = children as React.ReactElement<any>;
    const childProps = child.props || {};

    // Combine event handlers
    const mergedProps: Record<string, any> = { ...slotProps, ...childProps };

    // Combine className
    if (className || childProps.className) {
      mergedProps.className = cn(className, childProps.className);
    }

    // Combine style
    if (style || childProps.style) {
      mergedProps.style = { ...style, ...childProps.style };
    }

    // Combine event handlers (e.g. onClick)
    Object.keys(slotProps).forEach((propName) => {
      if (propName.startsWith("on") && typeof (slotProps as any)[propName] === "function") {
        const slotHandler = (slotProps as any)[propName];
        const childHandler = childProps[propName];

        mergedProps[propName] = (...args: any[]) => {
          childHandler?.(...args);
          slotHandler?.(...args);
        };
      }
    });

    // Merge refs safely across React 18 and 19
    const isReact19 = typeof React.version === "string" && React.version.startsWith("19");
    const childRef = isReact19 ? childProps.ref : ((child as any).ref ?? childProps.ref);

    if (forwardedRef || childRef) {
      mergedProps.ref = mergeRefs(forwardedRef, childRef);
    }

    return React.cloneElement(child, mergedProps);
  }

  if (React.Children.count(children) > 1) {
    React.Children.only(null);
  }

  return null;
});

Slot.displayName = "Slot";

export const Slottable: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  return <>{children}</>;
};

function mergeRefs<T = any>(...refs: (React.Ref<T> | undefined)[]): React.RefCallback<T> {
  return (node: T) => {
    refs.forEach((ref) => {
      if (!ref) return;
      if (typeof ref === "function") {
        ref(node);
      } else {
        (ref as React.MutableRefObject<T | null>).current = node;
      }
    });
  };
}

// packages/core/src/components/SplitTextReveal/SplitTextReveal.tsx
"use client";

import * as React from "react";
import { motion, useScroll, useTransform, useReducedMotion } from "framer-motion";
import { cn } from "../utils/cn";

export type SplitTextElement = "h1" | "h2" | "h3" | "h4" | "p" | "span" | "div";
export type SplitTextBy = "words" | "characters";

export interface SplitTextRevealProps extends React.HTMLAttributes<HTMLElement> {
  text: string;
  as?: SplitTextElement;
  by?: SplitTextBy;
  baseOpacity?: number;
  highlightColor?: string;
  scrollOffset?: [string, string];
  classNames?: {
    root?: string;
    token?: string;
  };
}

interface TokenRevealProps {
  token: string;
  progress: any;
  range: [number, number];
  baseOpacity: number;
  isReducedMotion: boolean | null;
  className?: string;
}

function TokenReveal({
  token,
  progress,
  range,
  baseOpacity,
  isReducedMotion,
  className,
}: TokenRevealProps) {
  const opacity = useTransform(
    progress,
    range,
    [baseOpacity, 1]
  );

  if (isReducedMotion) {
    return <span className={cn("inline-block", className)}>{token}</span>;
  }

  return (
    <motion.span
      style={{ opacity }}
      className={cn("inline-block will-change-[opacity]", className)}
    >
      {token}
    </motion.span>
  );
}

export const SplitTextReveal = React.forwardRef<HTMLElement, SplitTextRevealProps>(
  (
    {
      text,
      as: Tag = "h2",
      by = "words",
      baseOpacity = 0.2,
      scrollOffset = ["start 0.85", "end 0.35"],
      className,
      classNames,
      ...props
    },
    ref
  ) => {
    const internalRef = React.useRef<HTMLElement>(null);
    React.useImperativeHandle(ref, () => internalRef.current as HTMLElement);

    const isReducedMotion = useReducedMotion();

    const { scrollYProgress } = useScroll({
      target: internalRef,
      offset: scrollOffset as any,
    });

    const tokens = React.useMemo(() => {
      if (by === "characters") {
        return text.split("");
      }
      return text.split(" ");
    }, [text, by]);

    const total = tokens.length;

    return React.createElement(
      Tag,
      {
        ref: internalRef,
        className: cn(
          "inline-block flex-wrap font-display tracking-tight leading-[1.08] select-none",
          classNames?.root,
          className
        ),
        ...props,
      },
      tokens.map((token, index) => {
        // Calculate progressive reveal segment for each word or character
        const start = index / total;
        const end = Math.min(1, (index + 1) / total);

        return (
          <React.Fragment key={`${token}-${index}`}>
            <TokenReveal
              token={token}
              progress={scrollYProgress}
              range={[start, end]}
              baseOpacity={baseOpacity}
              isReducedMotion={isReducedMotion}
              className={classNames?.token}
            />
            {by === "words" && index < total - 1 ? " " : null}
          </React.Fragment>
        );
      })
    );
  }
);

SplitTextReveal.displayName = "SplitTextReveal";

