          )}
          aria-hidden="true"
        >
          {/* Thumb */}
          <span className={cn(switchThumbVariants({ size, isChecked: isCurrentChecked }))} />
        </div>

        {/* Label & Description Text */}
        {labelContent && (
          <div className="flex flex-col justify-center">
