// packages/core/src/components/Toast/Toast.tsx
"use client";

import * as React from "react";
import { CheckCircle2, AlertCircle, AlertTriangle, Info, Loader2, X } from "lucide-react";
import { cn } from "../utils/cn";

export type ToastType = "default" | "success" | "error" | "warning" | "info" | "loading";
export type ToastPosition =
  "top-left" | "top-right" | "top-center" | "bottom-left" | "bottom-right" | "bottom-center";

export interface ToastAction {
  label: string;
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
}

export interface ToastOptions {
  id?: string;
  type?: ToastType;
  title?: React.ReactNode;
  description?: React.ReactNode;
  duration?: number;
  icon?: React.ReactNode;
  action?: ToastAction;
  cancel?: ToastAction;
  onDismiss?: () => void;
  className?: string;
}

export interface ToastItem extends ToastOptions {
  id: string;
  createdAt: number;
  type: ToastType;
}

// ----------------------------------------------------
// Global Toast Event Bus & State Store
// ----------------------------------------------------

type ToastListener = (toasts: ToastItem[]) => void;
let toasts: ToastItem[] = [];
const listeners = new Set<ToastListener>();

function notify() {
  listeners.forEach((listener) => listener([...toasts]));
}

let toastCounter = 0;
function generateId(): string {
  toastCounter += 1;
  return `toast-${Date.now()}-${toastCounter}`;
}

export const toast = (title: React.ReactNode, options: ToastOptions = {}) => {
  const id = options.id || generateId();
  const newToast: ToastItem = {
    id,
    title,
    description: options.description,
    type: options.type || "default",
    duration: options.duration ?? 4000,
    icon: options.icon,
    action: options.action,
    cancel: options.cancel,
    onDismiss: options.onDismiss,
    className: options.className,
    createdAt: Date.now(),
  };

  // Replace if exists, else append
  const existingIdx = toasts.findIndex((t) => t.id === id);
  if (existingIdx !== -1) {
    toasts[existingIdx] = newToast;
  } else {
    toasts = [...toasts, newToast];
  }
  notify();
  return id;
};

toast.success = (title: React.ReactNode, options?: Omit<ToastOptions, "type">) =>
  toast(title, { ...options, type: "success" });

toast.error = (title: React.ReactNode, options?: Omit<ToastOptions, "type">) =>
  toast(title, { ...options, type: "error" });

toast.warning = (title: React.ReactNode, options?: Omit<ToastOptions, "type">) =>
  toast(title, { ...options, type: "warning" });

toast.info = (title: React.ReactNode, options?: Omit<ToastOptions, "type">) =>
  toast(title, { ...options, type: "info" });

toast.loading = (title: React.ReactNode, options?: Omit<ToastOptions, "type">) =>
  toast(title, { ...options, type: "loading", duration: Infinity });

toast.dismiss = (id?: string) => {
  if (id) {
    const item = toasts.find((t) => t.id === id);
    item?.onDismiss?.();
    toasts = toasts.filter((t) => t.id !== id);
  } else {
    toasts.forEach((t) => t.onDismiss?.());
    toasts = [];
  }
  notify();
};

toast.promise = async <T,>(
  promise: Promise<T> | (() => Promise<T>),
  msgs: {
    loading: React.ReactNode;
    success: React.ReactNode | ((data: T) => React.ReactNode);
    error: React.ReactNode | ((err: any) => React.ReactNode);
  },
  options?: ToastOptions
) => {
  const id = toast.loading(msgs.loading, options);
  try {
    const p = typeof promise === "function" ? promise() : promise;
    const res = await p;
    const successMsg = typeof msgs.success === "function" ? msgs.success(res) : msgs.success;
    toast.success(successMsg, { ...options, id });
    return res;
  } catch (err) {
    const errorMsg = typeof msgs.error === "function" ? msgs.error(err) : msgs.error;
    toast.error(errorMsg, { ...options, id });
    throw err;
  }
};

// ----------------------------------------------------
// Toast Component & Icons
// ----------------------------------------------------

const defaultIcons: Record<ToastType, React.ReactNode> = {
  default: null,
  success: <CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-500" />,
  error: <AlertCircle className="h-5 w-5 shrink-0 text-rose-500" />,
  warning: <AlertTriangle className="h-5 w-5 shrink-0 text-amber-500" />,
  info: <Info className="h-5 w-5 shrink-0 text-sky-500" />,
  loading: <Loader2 className="text-primary h-5 w-5 shrink-0 animate-spin" />,
};

interface SingleToastProps {
  toastItem: ToastItem;
}

const SingleToast: React.FC<SingleToastProps> = ({ toastItem }) => {
  const { id, title, description, type, icon, action, cancel, duration, className } = toastItem;

  React.useEffect(() => {
    if (duration === Infinity) return;
    const timer = setTimeout(() => {
      toast.dismiss(id);
    }, duration);
    return () => clearTimeout(timer);
  }, [id, duration]);

  const displayIcon = icon ?? defaultIcons[type];

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "animate-in fade-in-0 slide-in-from-bottom-2 pointer-events-auto relative flex w-full max-w-sm items-start gap-3 rounded-2xl border border-zinc-200/80 bg-white/95 p-4 shadow-xl shadow-zinc-950/5 backdrop-blur-md transition-all duration-300 dark:border-zinc-800 dark:bg-zinc-900/95 dark:shadow-black/20",
        type === "error" && "border-rose-200 dark:border-rose-900/40",
        type === "success" && "border-emerald-200 dark:border-emerald-900/40",
        type === "warning" && "border-amber-200 dark:border-amber-900/40",
        className
      )}
    >
      {displayIcon && <div className="mt-0.5 shrink-0">{displayIcon}</div>}

      <div className="flex-1 space-y-1 text-left">
        {title && (
          <h5 className="text-sm font-semibold tracking-tight text-zinc-900 dark:text-zinc-100">
            {title}
          </h5>
        )}
        {description && (
          <div className="text-xs leading-relaxed text-zinc-600 dark:text-zinc-400">
            {description}
          </div>
        )}

        {(action || cancel) && (
          <div className="flex items-center gap-2 pt-2">
            {action && (
              <button
                type="button"
                onClick={(e) => {
                  action.onClick(e);
                  toast.dismiss(id);
                }}
                className="rounded-lg bg-zinc-900 px-2.5 py-1 text-xs font-semibold text-white shadow-xs transition-colors hover:bg-zinc-800 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100"
              >
                {action.label}
              </button>
            )}
            {cancel && (
              <button
                type="button"
                onClick={(e) => {
                  cancel.onClick(e);
                  toast.dismiss(id);
                }}
                className="rounded-lg border border-zinc-200 px-2.5 py-1 text-xs font-medium text-zinc-700 hover:bg-zinc-100 dark:border-zinc-800 dark:text-zinc-300 dark:hover:bg-zinc-800"
              >
                {cancel.label}
              </button>
            )}
          </div>
        )}
      </div>

      <button
        type="button"
        aria-label="Dismiss toast"
        onClick={() => toast.dismiss(id)}
        className="-mt-1 -mr-1 rounded-lg p-1 text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-200"
      >
        <X className="h-4 w-4" />
      </button>
    </div>
  );
};

// ----------------------------------------------------
// Toaster Container Component
// ----------------------------------------------------

export interface ToasterProps {
  position?: ToastPosition;
  className?: string;
  maxToasts?: number;
}

const positionClasses: Record<ToastPosition, string> = {
  "top-left": "top-4 left-4 items-start",
  "top-center": "top-4 left-1/2 -translate-x-1/2 items-center",
  "top-right": "top-4 right-4 items-end",
  "bottom-left": "bottom-4 left-4 items-start",
  "bottom-center": "bottom-4 left-1/2 -translate-x-1/2 items-center",
  "bottom-right": "bottom-4 right-4 items-end",
};

export const Toaster: React.FC<ToasterProps> = ({
  position = "bottom-right",
  className,
  maxToasts = 5,
}) => {
  const [activeToasts, setActiveToasts] = React.useState<ToastItem[]>([]);

  React.useEffect(() => {
    const handleUpdate = (newList: ToastItem[]) => {
      setActiveToasts(newList);
    };

    listeners.add(handleUpdate);
    setActiveToasts([...toasts]);

    return () => {
      listeners.delete(handleUpdate);
    };
  }, []);

  const visibleToasts = activeToasts.slice(-maxToasts);

  if (visibleToasts.length === 0) return null;

  return (
    <div
      aria-label="Notifications"
      className={cn(
        "pointer-events-none fixed z-[9999] flex w-full max-w-sm flex-col gap-2.5 p-4 sm:p-0",
        positionClasses[position],
        className
      )}
    >
      {visibleToasts.map((item) => (
        <SingleToast key={item.id} toastItem={item} />
      ))}
    </div>
  );
};

Toaster.displayName = "Toaster";

// packages/core/src/components/Tooltip/Tooltip.tsx
"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../utils/cn";

export type TooltipPlacement = "top" | "bottom" | "left" | "right";
export type TooltipColor =
  "default" | "foreground" | "primary" | "secondary" | "success" | "warning" | "danger";
export type TooltipSize = "sm" | "md" | "lg";
export type TooltipRadius = "none" | "sm" | "md" | "lg" | "full";

export const tooltipVariants = cva(
  "z-50 px-3 py-1.5 font-medium leading-tight shadow-md select-none pointer-events-none transition-all duration-150 ease-out whitespace-nowrap",
  {
    variants: {
      color: {
        default:
          "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-950 border border-zinc-800 dark:border-zinc-200",
        foreground:
          "bg-zinc-950 text-white dark:bg-white dark:text-zinc-950 border border-zinc-900 dark:border-zinc-100",
        primary: "bg-primary text-primary-foreground",
        secondary: "bg-purple-600 text-white dark:bg-purple-500",
        success: "bg-emerald-600 text-white dark:bg-emerald-500",
        warning: "bg-amber-500 text-zinc-950 dark:bg-amber-400",
        danger: "bg-rose-600 text-white dark:bg-rose-500",
      },
      size: {
        sm: "text-[11px] px-2 py-0.5 min-h-6",
        md: "text-xs px-2.5 py-1 min-h-7",
        lg: "text-sm px-3.5 py-1.5 min-h-8",
      },
      radius: {
        none: "rounded-none",
        sm: "rounded-sm",
        md: "rounded-md",
        lg: "rounded-lg",
        full: "rounded-full",
      },
    },
    defaultVariants: {
      color: "default",
      size: "md",
      radius: "md",
    },
  }
);

// Matching arrow styles for each color
const arrowColorStyles: Record<TooltipColor, string> = {
  default: "bg-zinc-900 dark:bg-zinc-100 border-zinc-800 dark:border-zinc-200",
  foreground: "bg-zinc-950 dark:bg-white border-zinc-900 dark:border-zinc-100",
  primary: "bg-primary",
  secondary: "bg-purple-600 dark:bg-purple-500",
  success: "bg-emerald-600 dark:bg-emerald-500",
  warning: "bg-amber-500 dark:bg-amber-400",
  danger: "bg-rose-600 dark:bg-rose-500",
};

export interface TooltipProps extends VariantProps<typeof tooltipVariants> {
  content: React.ReactNode;
  children: React.ReactElement;
  placement?: TooltipPlacement;
  delay?: number;
  closeDelay?: number;
  offset?: number;
  showArrow?: boolean;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  isDisabled?: boolean;
  className?: string;
  classNames?: {
    base?: string;
    content?: string;
    arrow?: string;
  };
}

export const Tooltip: React.FC<TooltipProps> = ({
  content,
  children,
  placement = "top",
  color = "default",
  size = "md",
  radius = "md",
  delay = 150,
  closeDelay = 100,
  offset = 8,
  showArrow = true,
  isOpen: propIsOpen,
  defaultOpen = false,
  onOpenChange,
  isDisabled = false,
  className,
  classNames,
}) => {
  const tooltipId = React.useId();
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const openTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const closeTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const isControlled = propIsOpen !== undefined;
  const isVisible = isControlled ? propIsOpen : uncontrolledOpen;

  const clearTimers = React.useCallback(() => {
    if (openTimerRef.current) clearTimeout(openTimerRef.current);
    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
  }, []);

  const handleOpen = React.useCallback(() => {
    if (isDisabled) return;
    clearTimers();
    if (delay === 0) {
      if (!isControlled) setUncontrolledOpen(true);
      onOpenChange?.(true);
    } else {
      openTimerRef.current = setTimeout(() => {
        if (!isControlled) setUncontrolledOpen(true);
        onOpenChange?.(true);
      }, delay);
    }
  }, [isDisabled, clearTimers, delay, isControlled, onOpenChange]);

  const handleClose = React.useCallback(() => {
    clearTimers();
    if (closeDelay === 0) {
      if (!isControlled) setUncontrolledOpen(false);
      onOpenChange?.(false);
    } else {
      closeTimerRef.current = setTimeout(() => {
        if (!isControlled) setUncontrolledOpen(false);
        onOpenChange?.(false);
      }, closeDelay);
    }
  }, [clearTimers, closeDelay, isControlled, onOpenChange]);

  React.useEffect(() => {
    return () => clearTimers();
  }, [clearTimers]);

  // Position offsets and arrow coordinates
  const positionClasses = React.useMemo(() => {
    switch (placement) {
      case "top":
        return "bottom-full left-1/2 -translate-x-1/2 mb-2 origin-bottom";
      case "bottom":
        return "top-full left-1/2 -translate-x-1/2 mt-2 origin-top";
      case "left":
        return "right-full top-1/2 -translate-y-1/2 mr-2 origin-right";
      case "right":
        return "left-full top-1/2 -translate-y-1/2 ml-2 origin-left";
      default:
        return "bottom-full left-1/2 -translate-x-1/2 mb-2 origin-bottom";
    }
  }, [placement]);

  const arrowClasses = React.useMemo(() => {
    switch (placement) {
      case "top":
        return "bottom-[-4px] left-1/2 -translate-x-1/2 border-b border-r rotate-45";
      case "bottom":
        return "top-[-4px] left-1/2 -translate-x-1/2 border-t border-l rotate-45";
      case "left":
        return "right-[-4px] top-1/2 -translate-y-1/2 border-t border-r rotate-45";
      case "right":
        return "left-[-4px] top-1/2 -translate-y-1/2 border-b border-l rotate-45";
      default:
        return "bottom-[-4px] left-1/2 -translate-x-1/2 border-b border-r rotate-45";
    }
  }, [placement]);

  if (!React.isValidElement(children)) {
    return children;
  }

  const childElement = children as React.ReactElement<any>;
  const childProps = childElement.props || {};

  // Clone child with interactive event triggers and accessible ARIA attributes
  const trigger = React.cloneElement(childElement, {
    "aria-describedby": isVisible && !isDisabled ? tooltipId : undefined,
    onMouseEnter: (e: React.MouseEvent) => {
      childProps.onMouseEnter?.(e);
      handleOpen();
    },
    onMouseLeave: (e: React.MouseEvent) => {
      childProps.onMouseLeave?.(e);
      handleClose();
    },
    onFocus: (e: React.FocusEvent) => {
      childProps.onFocus?.(e);
      handleOpen();
    },
    onBlur: (e: React.FocusEvent) => {
      childProps.onBlur?.(e);
      handleClose();
    },
    onKeyDown: (e: React.KeyboardEvent) => {
      childProps.onKeyDown?.(e);
      if (e.key === "Escape") {
        handleClose();
      }
    },
  });

  return (
    <div className={cn("relative inline-flex items-center", classNames?.base)}>
      {trigger}

      {isVisible && !isDisabled && (
        <div
          id={tooltipId}
          role="tooltip"
          className={cn(
            "animate-in fade-in-0 zoom-in-95 absolute duration-150",
            positionClasses,
            tooltipVariants({ color, size, radius }),
            classNames?.content,
            className
          )}
          style={{
            // Adjust margin based on custom offset if needed
            ...(placement === "top" && { marginBottom: `${offset}px` }),
            ...(placement === "bottom" && { marginTop: `${offset}px` }),
            ...(placement === "left" && { marginRight: `${offset}px` }),
            ...(placement === "right" && { marginLeft: `${offset}px` }),
          }}
        >
          {content}
          {showArrow && (
            <span
              aria-hidden="true"
              className={cn(
                "absolute h-2 w-2",
                arrowClasses,
                arrowColorStyles[color || "default"],
                classNames?.arrow
              )}
            />
          )}
        </div>
      )}
    </div>
  );
};

Tooltip.displayName = "Tooltip";

