import { cn } from "../utils/cn";
import { motion, useScroll, useTransform, useInView } from "framer-motion";

const featureSectionVariants = cva("py-24 sm:py-32 overflow-hidden relative", {
  variants: {
    variant: {
      default: "bg-white dark:bg-zinc-950",
      subtle: "bg-zinc-50 dark:bg-[#0a0a0a]",
      transparent: "bg-transparent",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export interface FeatureSectionProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof featureSectionVariants> {}

const FeatureSection = React.forwardRef<HTMLDivElement, FeatureSectionProps>(
  ({ className, variant, ...props }, ref) => {
    return (
      <div ref={ref} className={cn(featureSectionVariants({ variant }), className)} {...props} />
    );
  }
);
FeatureSection.displayName = "FeatureSection";

const FeatureHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn("relative z-10 mx-auto mb-16 max-w-7xl px-6 sm:mb-20 lg:px-8", className)}
        {...props}
      >
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.7 }}
          className="mx-auto max-w-2xl text-center"
        >
          {children}
        </motion.div>
      </div>
    );
  }
);
FeatureHeader.displayName = "Feature.Header";

const FeatureBadge = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(
  ({ className, ...props }, ref) => {
    return (
      <h2
        ref={ref}
        className={cn(
          "mx-auto inline-flex w-fit rounded-full px-4 py-1.5 text-base leading-7 font-semibold text-blue-600 dark:text-blue-400",
          className
        )}
        {...props}
      />
    );
  }
);
FeatureBadge.displayName = "Feature.Badge";

const FeatureTitle = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(
  ({ className, ...props }, ref) => {
    return (
      <p
        ref={ref}
        className={cn(
          "mt-2 text-3xl font-bold tracking-tight text-balance text-zinc-900 sm:text-4xl dark:text-white",
          className
        )}
        {...props}
      />
    );
  }
);
FeatureTitle.displayName = "Feature.Title";

const FeatureDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => {
  return (
    <p
      ref={ref}
      className={cn("mt-6 text-lg leading-8 text-zinc-600 dark:text-zinc-400", className)}
      {...props}
    />
  );
});
FeatureDescription.displayName = "Feature.Description";

// --- Grid Layout ---

const FeatureGrid = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    return (
      <div ref={ref} className={cn("relative z-10 mx-auto max-w-7xl px-6 lg:px-8", className)}>
        <div
          className="mx-auto grid max-w-2xl grid-cols-1 gap-x-8 gap-y-16 sm:gap-y-20 lg:mx-0 lg:max-w-none lg:grid-cols-3"
          {...props}
        />
      </div>
    );
  }
);
FeatureGrid.displayName = "Feature.Grid";

const FeatureCard = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { index?: number }
>(({ className, index = 0, children, ...props }, ref) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-100px" }}
      transition={{ duration: 0.5, delay: index * 0.1 }}
      ref={ref}
      className={cn("flex flex-col", className)}
      {...(props as any)}
    >
      {children}
    </motion.div>
  );
});
FeatureCard.displayName = "Feature.Card";

export interface FeatureIconProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Override the icon container colors.
   * e.g. "bg-violet-600 text-white ring-violet-500/30 dark:bg-violet-500/20 dark:text-violet-400"
   */
  iconClassName?: string;
}

const FeatureIcon = React.forwardRef<HTMLDivElement, FeatureIconProps>(
  ({ className, iconClassName, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "mb-6 flex h-10 w-10 items-center justify-center rounded-lg",
          iconClassName ??
            "bg-blue-600 text-white ring-1 ring-blue-500/30 dark:bg-blue-500/20 dark:text-blue-400",
          className
        )}
        {...props}
      />
    );
  }
);
FeatureIcon.displayName = "Feature.Icon";

const FeatureCardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => {
  return (
    <dt
      ref={ref}
      className={cn("text-base leading-7 font-semibold text-zinc-900 dark:text-white", className)}
      {...props}
    />
  );
});
FeatureCardTitle.displayName = "Feature.CardTitle";

const FeatureCardDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => {
  return (
    <dd
      ref={ref}
      className={cn(
        "mt-1 flex flex-auto flex-col text-base leading-7 text-zinc-600 dark:text-zinc-400",
        className
      )}
      {...props}
    />
  );
});
FeatureCardDescription.displayName = "Feature.CardDescription";

// --- Alternating Layout ---

const FeatureAlternating = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "relative z-10 mx-auto max-w-7xl space-y-24 px-6 sm:space-y-32 lg:px-8",
          className
        )}
        {...props}
      />
    );
  }
);
FeatureAlternating.displayName = "Feature.Alternating";

const FeatureRow = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { reverse?: boolean }
>(({ className, reverse = false, children, ...props }, ref) => {
  return (
    <div
      ref={ref}
      className={cn("grid grid-cols-1 items-center gap-x-12 gap-y-16 lg:grid-cols-2", className)}
      {...props}
    >
      {React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) return child;

        const isText = child.type === FeatureRowContent;
        const orderClass = reverse
          ? isText
            ? "lg:order-2"
            : "lg:order-1"
          : isText
            ? "lg:order-1"
            : "lg:order-2";

        const typedChild = child as React.ReactElement<{ className?: string }>;
        return React.cloneElement(typedChild, {
          className: cn(typedChild.props.className, orderClass),
        });
      })}
    </div>
  );
});
FeatureRow.displayName = "Feature.Row";

const FeatureRowContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    return (
      <motion.div
        initial={{ opacity: 0, x: -30 }}
        whileInView={{ opacity: 1, x: 0 }}
        viewport={{ once: true, margin: "-100px" }}
        transition={{ duration: 0.7 }}
        ref={ref}
        className={cn("max-w-xl", className)}
        {...(props as any)}
      />
    );
  }
);
FeatureRowContent.displayName = "Feature.RowContent";

const FeatureRowMedia = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    return (
      <motion.div
        initial={{ opacity: 0, x: 30 }}
        whileInView={{ opacity: 1, x: 0 }}
        viewport={{ once: true, margin: "-100px" }}
        transition={{ duration: 0.7 }}
        ref={ref}
        className={cn(
          "relative overflow-hidden rounded-2xl bg-zinc-100 p-2 ring-1 ring-zinc-900/10 backdrop-blur-sm sm:p-4 dark:bg-zinc-900/50 dark:ring-white/10",
          className
        )}
        {...(props as any)}
      >
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-tr from-indigo-500/10 via-transparent to-purple-500/10" />
        {children}
      </motion.div>
    );
  }
);
FeatureRowMedia.displayName = "Feature.RowMedia";

export {
  FeatureSection,
  FeatureHeader,
  FeatureBadge,
  FeatureTitle,
  FeatureDescription,
  FeatureGrid,
  FeatureCard,
  FeatureIcon,
  FeatureCardTitle,
  FeatureCardDescription,
  FeatureAlternating,
  FeatureRow,
  FeatureRowContent,
  FeatureRowMedia,
};

"use client";

import React from "react";
import { motion } from "framer-motion";
import { cn } from "../utils/cn";

export interface FeatureGlassItem {
  icon: React.ReactNode;
  title: string;
  description: string;
}

export interface FeatureGlassProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  badge?: React.ReactNode;
  title?: React.ReactNode;
  description?: React.ReactNode;
  features: FeatureGlassItem[];
  /**
   * Override the decorative glow orb color inside each card.
   * e.g. "bg-violet-500/10 dark:bg-violet-500/20"
   */
  glowClassName?: string;
  /**
   * Override the icon container colors.
   * e.g. "bg-violet-600/10 text-violet-600 ring-violet-600/20 dark:bg-violet-500/20 dark:text-violet-300 dark:ring-violet-500/30"
   */
  iconClassName?: string;
}

export const FeatureGlass = React.forwardRef<HTMLElement, FeatureGlassProps>(
  (
    {
      className,
      badge,
      title = "Everything you need.",
      description = "A complete toolkit to build better, faster, and more beautifully.",
      features,
      glowClassName = "bg-blue-500/10 dark:bg-blue-500/20",
      iconClassName = "bg-blue-600/10 text-blue-600 ring-blue-600/20 dark:bg-blue-500/20 dark:text-blue-300 dark:ring-blue-500/30",
      ...props
    },
    ref
  ) => {
    return (
      <section
        ref={ref}
        className={cn("relative overflow-hidden py-24 sm:py-32", className)}
        {...props}
      >
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {/* Header */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.5 }}
            className="mx-auto mb-16 max-w-3xl text-center sm:mb-20"
          >
            {badge && <div className="mb-6 flex justify-center">{badge}</div>}
            <h2 className="text-3xl font-bold tracking-tight text-zinc-900 sm:text-5xl dark:text-white">
              {title}
            </h2>
            {description && (
              <p className="mx-auto mt-6 max-w-2xl text-lg leading-8 text-zinc-600 dark:text-zinc-400">
                {description}
              </p>
            )}
          </motion.div>

          {/* Grid */}
          <div className="grid grid-cols-1 gap-8 md:grid-cols-2 lg:grid-cols-3">
            {features.map((feature, idx) => (
              <motion.div
                key={idx}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-50px" }}
                transition={{ duration: 0.5, delay: idx * 0.1 }}
                className="group relative overflow-hidden rounded-3xl border border-white/50 bg-white/40 p-8 shadow-[0_8px_30px_rgb(0,0,0,0.04)] backdrop-blur-xl transition-all hover:bg-white/60 dark:border-white/10 dark:bg-zinc-900/40 dark:shadow-[0_8px_30px_rgb(0,0,0,0.5)] dark:hover:bg-zinc-900/60"
              >
                {/* Decorative glowing orb inside the card */}
                <div
                  className={cn(
                    "absolute -top-12 -right-12 h-32 w-32 rounded-full blur-2xl transition-transform group-hover:scale-150",
                    glowClassName
                  )}
                />

                <div
                  className={cn(
                    "relative z-10 flex h-12 w-12 items-center justify-center rounded-xl shadow-sm ring-1 ring-inset",
                    iconClassName
                  )}
                >
                  {feature.icon}
                </div>
                <div className="relative z-10 mt-6">
                  <h3 className="text-lg leading-7 font-semibold text-zinc-900 dark:text-white">
                    {feature.title}
                  </h3>
                  <p className="mt-2 text-base leading-7 text-zinc-600 dark:text-zinc-400">
                    {feature.description}
                  </p>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>
    );
  }
);

FeatureGlass.displayName = "FeatureGlass";

"use client";

import React from "react";
import { motion } from "framer-motion";
import { cn } from "../utils/cn";

export interface FooterGlassProps extends React.HTMLAttributes<HTMLElement> {
  logo?: React.ReactNode;
  brandName?: string;
  newsletterTitle?: string;
  newsletterDisclaimer?: string;
  newsletterPlaceholder?: string;
  newsletterButtonText?: string;
  onSubscribe?: (email: string) => void;
  linkGroups?: { title: string; links: { label: string; href: string }[] }[];
  copyright?: string;
}

export const FooterGlass = React.forwardRef<HTMLElement, FooterGlassProps>(
  (
    {
      className,
      logo,
      brandName,
      newsletterTitle = "Sign up to receive updates.",
      newsletterDisclaimer = "By subscribing you agree to with our Privacy Policy and provide consent to receive updates from our company.",
      newsletterPlaceholder = "Enter your email",
      newsletterButtonText = "Submit",
      onSubscribe,
      linkGroups = [],
      copyright,
      ...props
    },
    ref
  ) => {
    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      const formData = new FormData(e.currentTarget);
      const email = formData.get("email") as string;
      if (email && onSubscribe) {
        onSubscribe(email);
      }
    };

    return (
      <footer ref={ref} className={cn("py-12 md:py-16 lg:py-20", className)} {...props}>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8"
        >
          <div className="overflow-hidden rounded-[2rem] border border-white/50 bg-white/40 p-8 shadow-[0_8px_30px_rgb(0,0,0,0.04)] backdrop-blur-2xl sm:p-12 dark:border-white/10 dark:bg-black/20 dark:shadow-[0_8px_30px_rgb(0,0,0,0.5)]">
            <div className="flex flex-col justify-between gap-12 lg:flex-row">
              {/* Left Column: Brand & Newsletter */}
              <div className="w-full max-w-sm">
                <div className="mb-8 flex items-center gap-2">
                  {logo}
                  {brandName && (
                    <span className="text-xl font-bold tracking-tight text-zinc-900 dark:text-white">
                      {brandName}
                    </span>
                  )}
                </div>

                <div className="mb-6">
                  <h3 className="text-sm font-semibold text-zinc-900 dark:text-white">
                    {newsletterTitle}
                  </h3>
                  <form
                    onSubmit={handleSubmit}
                    className="mt-4 flex rounded-full border border-zinc-200/50 bg-white/50 p-1 backdrop-blur-md dark:border-zinc-800/50 dark:bg-black/50"
                  >
                    <input
                      name="email"
                      type="email"
                      required
                      placeholder={newsletterPlaceholder}
                      className="w-full min-w-0 bg-transparent px-4 py-2 text-sm text-zinc-900 outline-none placeholder:text-zinc-500 dark:text-white dark:placeholder:text-zinc-400"
                      aria-label="Email address"
                    />
                    <button
                      type="submit"
                      className="shrink-0 rounded-full bg-zinc-900 px-6 py-2 text-sm font-medium text-white transition-colors hover:bg-zinc-800 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100"
                    >
                      {newsletterButtonText}
                    </button>
                  </form>
                  {newsletterDisclaimer && (
                    <p className="mt-4 text-[10px] leading-relaxed text-zinc-500 dark:text-zinc-400">
                      {newsletterDisclaimer}
                    </p>
                  )}
                </div>
              </div>

              {/* Right Column: Links */}
              <div className="grid grid-cols-2 gap-8 sm:grid-cols-4 lg:gap-12">
                {linkGroups.map((group, idx) => (
                  <div key={idx}>
                    <h3 className="mb-4 text-xs font-semibold tracking-wide text-zinc-900 dark:text-zinc-100">
                      {group.title}
                    </h3>
                    <ul className="space-y-3">
                      {group.links.map((link, linkIdx) => (
                        <li key={linkIdx}>
                          <a
                            href={link.href}
                            className="text-xs text-zinc-600 transition-colors hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
                          >
                            {link.label}
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>
            </div>

            {/* Bottom Bar: Copyright */}
            <div className="mt-12 flex justify-center border-t border-zinc-200/50 pt-8 dark:border-zinc-800/50">
              {copyright && <p className="text-xs text-zinc-500 dark:text-zinc-400">{copyright}</p>}
            </div>
          </div>
        </motion.div>
      </footer>
    );
  }
);

FooterGlass.displayName = "FooterGlass";

"use client";

import React from "react";
import { motion } from "framer-motion";
import { cn } from "../utils/cn";
import { Input } from "../Input";
import { Button } from "../Button";

export interface FooterLinkGroup {
  title: string;
  links: { label: string; href?: string; badge?: React.ReactNode }[];
  action?: React.ReactNode;
}

export interface FooterMegaProps extends React.HTMLAttributes<HTMLElement> {
  logo?: React.ReactNode;
  brandName?: string;
  description?: string;
  linkGroups?: FooterLinkGroup[];
  socials?: { label: string; href: string; icon: React.ReactNode }[];
  copyright?: string;
  newsletterTitle?: string;
  newsletterDescription?: string;
  newsletterPlaceholder?: string;
  newsletterButtonText?: string;
  onSubscribe?: (email: string) => void;
  hideNewsletter?: boolean;
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.07, delayChildren: 0.1 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 16 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.45 } },
};

export const FooterMega = React.forwardRef<HTMLElement, FooterMegaProps>(
  (
    {
      className,
      logo,
      brandName,
      description,
      linkGroups = [],
      socials = [],
      copyright,
      newsletterTitle = "Subscribe to our newsletter",
      newsletterDescription = "The latest news, articles, and resources, sent to your inbox weekly.",
      newsletterPlaceholder = "Enter your email",
      newsletterButtonText = "Subscribe",
      onSubscribe,
      hideNewsletter = false,
      ...props
    },
    ref
  ) => {
    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      const formData = new FormData(e.currentTarget);
      const email = formData.get("email") as string;
      if (email && onSubscribe) {
        onSubscribe(email);
      }
    };

    return (
      <footer ref={ref} className={cn("py-12 md:py-16 lg:py-20", className)} {...props}>
        <motion.div
          initial="hidden"
          animate="visible"
          variants={containerVariants}
          className="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8"
        >
          {hideNewsletter ? (
            /* ── Wide layout (no newsletter): logo left + dense multi-column links ── */
            <div className="flex flex-col gap-12 lg:flex-row lg:gap-16">
              {/* Logo + tagline */}
              <motion.div variants={itemVariants} className="shrink-0 lg:w-52">
                <div className="flex items-center gap-2">
                  {logo}
                  {brandName && (
                    <span className="text-lg font-bold tracking-tight text-zinc-900 dark:text-white">
                      {brandName}
                    </span>
                  )}
                </div>
                {description && (
                  <p className="mt-4 text-sm leading-relaxed text-zinc-600 dark:text-zinc-400">
                    {description}
                  </p>
                )}
              </motion.div>

              {/* Dense links grid – auto-fills columns */}
              <div className="grid flex-1 grid-cols-2 gap-x-6 gap-y-10 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6">
                {linkGroups.map((group, idx) => (
                  <motion.div key={idx} variants={itemVariants}>
                    <h3 className="text-xs font-semibold tracking-widest text-zinc-900 uppercase dark:text-white">
                      {group.title}
                    </h3>
                    <ul className="mt-4 space-y-2.5">
                      {group.links.map((link, linkIdx) => (
                        <li key={linkIdx}>
                          {link.href ? (
                            <a
                              href={link.href}
                              className="flex items-center gap-1.5 text-sm text-zinc-600 transition-colors hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
                            >
                              {link.label}
                              {link.badge && link.badge}
                            </a>
                          ) : (
                            <div className="flex cursor-not-allowed items-center gap-1.5 text-sm text-zinc-400 select-none dark:text-zinc-500">
                              {link.label}
                              {link.badge && link.badge}
                            </div>
                          )}
                        </li>
                      ))}
                    </ul>
                    {group.action && <div className="mt-4">{group.action}</div>}
                  </motion.div>
                ))}
              </div>
            </div>
          ) : (
            /* ── Default layout: brand + newsletter on left, links on right ── */
            <div className="grid grid-cols-1 gap-12 lg:grid-cols-12 lg:gap-8">
              <motion.div variants={itemVariants} className="lg:col-span-5">
                <div className="flex items-center gap-3">
                  {logo}
                  {brandName && (
                    <span className="text-2xl font-bold tracking-tight text-zinc-900 dark:text-white">
                      {brandName}
                    </span>
                  )}
                </div>
                {description && (
                  <p className="mt-4 max-w-md text-base text-zinc-600 dark:text-zinc-400">
                    {description}
                  </p>
                )}
                <div className="mt-8">
                  <h3 className="text-sm font-semibold text-zinc-900 dark:text-white">
                    {newsletterTitle}
                  </h3>
                  <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
                    {newsletterDescription}
                  </p>
                  <form onSubmit={handleSubmit} className="mt-4 flex max-w-md gap-2">
                    <Input
                      name="email"
                      type="email"
                      required
                      placeholder={newsletterPlaceholder}
                      className="w-full"
                      aria-label="Email address"
                    />
                    <Button type="submit" variant="solid" color="zinc" className="shrink-0">
                      {newsletterButtonText}
                    </Button>
                  </form>
                </div>
              </motion.div>

              <div className="grid grid-cols-2 gap-8 sm:grid-cols-3 lg:col-span-7 lg:pl-16">
                {linkGroups.map((group, idx) => (
                  <motion.div key={idx} variants={itemVariants}>
                    <h3 className="text-sm font-semibold text-zinc-900 dark:text-white">
                      {group.title}
                    </h3>
                    <ul className="mt-4 space-y-3">
                      {group.links.map((link, linkIdx) => (
                        <li key={linkIdx}>
                          {link.href ? (
                            <a
                              href={link.href}
                              className="flex items-center gap-2 text-sm text-zinc-600 transition-colors hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-white"
                            >
                              {link.label}
                              {link.badge && link.badge}
                            </a>
                          ) : (
                            <div className="flex cursor-not-allowed items-center gap-2 text-sm text-zinc-400 dark:text-zinc-500">
